/* DAWAH X — ahmad, অধ্যায় 52 · খণ্ড 52 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][52]=[[10201,10201,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقْرَضَ مِنْ رَجُلٍ بَعِيرًا فَجَاءَ ‏ ‏يَتَقَاضَاهُ ‏ ‏بَعِيرَهُ فَقَالَ اطْلُبُوا لَهُ بَعِيرًا فَادْفَعُوهُ إِلَيْهِ فَلَمْ يَجِدُوا إِلَّا ‏ ‏سِنًّا ‏ ‏فَوْقَ سِنِّهِ فَقَالُوا يَا رَسُولَ اللَّهِ لَمْ نَجِدْ إِلَّا ‏ ‏سِنًّا ‏ ‏فَوْقَ ‏ ‏سِنِّ ‏ ‏بَعِيرِهِ فَقَالَ ‏ ‏أَعْطُوهُ فَإِنَّ خِيَارَكُمْ أَحَاسِنُكُمْ ‏ ‏قَضَاءً ‏","","",""],[10202,10202,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَيَرْفَعُ الدَّرَجَةَ لِلْعَبْدِ الصَّالِحِ فِي الْجَنَّةِ فَيَقُولُ يَا رَبِّ أَنَّى لِي هَذِهِ فَيَقُولُ بِاسْتِغْفَارِ وَلَدِكَ لَكَ ‏","","",""],[10203,10203,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلُّوا فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ وَلَا تُصَلُّوا فِي ‏ ‏مَعَاطِنِ ‏ ‏الْإِبِلِ ‏","","",""],[10204,10204,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُولُوا لِلْعِنَبِ الْكَرْمَ فَإِنَّ الْكَرْمَ الرَّجُلُ الْمُسْلِمُ الصَّالِحُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَحْوِهِ ‏","","",""],[10205,10205,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنِ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَهِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُدْخِلُ أَحَدًا مِنْكُمْ عَمَلُهُ الْجَنَّةَ قِيلَ وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ بِرَحْمَةٍ مِنْهُ وَفَضْلٍ وَوَضَعَ يَدَهُ عَلَى رَأْسِهِ ‏","","",""],[10206,10206,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏سَمِعَ ‏ ‏أَبَاهُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ إِذَا أَحَبَّ اللَّهُ عَبْدًا قَالَ يَا ‏ ‏جِبْرِيلُ ‏ ‏إِنِّي أُحِبُّ فُلَانًا فَأَحِبُّوهُ فَيُنَادِي ‏ ‏جِبْرِيلُ ‏ ‏فِي السَّمَاوَاتِ إِنَّ اللَّهَ عَزَّ وَجَلَّ يُحِبُّ فُلَانًا فَأَحِبُّوهُ ‏ ‏فَيُلْقَى حُبُّهُ عَلَى أَهْلِ الْأَرْضِ فَيُحَبُّ وَإِذَا أَبْغَضَ عَبْدًا قَالَ يَا ‏ ‏جِبْرِيلُ ‏ ‏إِنِّي أُبْغِضُ فُلَانًا فَأَبْغِضُوهُ فَيُنَادِي ‏ ‏جِبْرِيلُ ‏ ‏فِي السَّمَاوَاتِ إِنَّ اللَّهَ عَزَّ وَجَلَّ يُبْغِضُ فُلَانًا فَأَبْغِضُوهُ فَيُوضَعُ لَهُ الْبُغْضُ لِأَهْلِ الْأَرْضِ فَيُبْغَضُ ‏","","",""],[10207,10207,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏مَوْلَى ‏ ‏أُمِّ بُرْثُنٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ كَتَبَ الْجُمُعَةَ عَلَى مَنْ كَانَ قَبْلَنَا فَاخْتَلَفُوا فِيهَا وَهَدَانَا اللَّهُ لَهَا فَالنَّاسُ لَنَا فِيهَا تَبَعٌ فَالْيَوْمُ لَنَا ‏ ‏ولِلْيَهُودِ ‏ ‏غَدًا ‏ ‏وَلِلنَّصَارَى ‏ ‏بَعْدَ غَدٍ ‏","","",""],[10208,10208,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏جُهَيْرُ بْنُ يَزِيدَ الْعَبْدِيُّ ‏ ‏عَنْ ‏ ‏خِدَاشِ بْنِ عَيَّاشٍ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي حَلْقَةٍ ‏ ‏بِالْكُوفَةِ ‏ ‏فَإِذَا ‏ ‏رَجُلٌ ‏ ‏يُحَدِّثُ قَالَ ‏ ‏كُنَّا جُلُوسًا مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَقَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ شَهِدَ عَلَى مُسْلِمٍ شَهَادَةً لَيْسَ لَهَا بِأَهْلٍ ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[10209,10209,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ صَفِيَّةَ ‏ ‏وَقَالَ ‏ ‏يَعْقُوبُ ‏ ‏صُبَيَّةَ ‏ ‏وَهُوَ الصَّوَابُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ وَلَأَخَّرْتُ صَلَاةَ الْعِشَاءِ الْآخِرَةِ إِلَى ثُلُثِ اللَّيْلِ الْأَوَّلِ فَإِنَّهُ إِذَا مَضَى ثُلُثُ اللَّيْلِ الْأَوَّلُ هَبَطَ إِلَى السَّمَاءِ الدُّنْيَا إِلَى طُلُوعِ الْفَجْرِ يَقُولُ قَائِلٌ أَلَا دَاعٍ يُجَابُ أَلَا سَائِلٌ يُعْطِيهِ أَلَا مُذْنِبٌ يَسْتَغْفِرُ فَيُغْفَرَ لَهُ ‏","","",""],[10210,10210,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ يَعْنِي التَّيْمِيَّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَعْنِي الرَّبَّ عَزَّ وَجَلَّ ‏ ‏إِذَا تَقَرَّبَ الْعَبْدُ مِنِّي شِبْرًا تَقَرَّبْتُ مِنْهُ ذِرَاعًا وَإِذَا تَقَرَّبَ مِنِّي ذِرَاعًا تَقَرَّبْتُ مِنْهُ بُوعًا أَوْ بَاعًا وَإِذَا تَقَرَّبَ مِنِّي بُوعًا أَوْ بَاعًا أَتَيْتُهُ هَرْوَلَةً ‏","","",""],[10211,10211,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي السَّلِيلِ ‏ ‏عَنْ ‏ ‏أَبِي حَسَّانَ ‏ ‏قَالَ ‏ ‏تُوُفِّيَ ابْنَانِ فَقُلْتُ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا تُحَدِّثُنَاهُ تُطَيِّبُ بِنَفْسِنَا عَنْ مَوْتَانَا قَالَ نَعَمْ ‏ ‏صِغَارُهُمْ ‏ ‏دَعَامِيصُ ‏ ‏الْجَنَّةِ يَلْقَى أَحَدُهُمْ أَبَاهُ أَوْ أَبَوَيْهِ فَيَأْخُذُ بِنَاحِيَةِ ثَوْبِهِ أَوْ يَدِهِ كَمَا آخُذُ ‏ ‏بِصَنِفَةِ ‏ ‏ثَوْبِكَ هَذَا فَلَا يُفَارِقُهُ حَتَّى يُدْخِلَهُ وَأَبَاهُ الْجَنَّةَ ‏","","",""],[10212,10212,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏عَوْفٌ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غُفِرَ لِامْرَأَةٍ ‏ ‏مُومِسَةٍ ‏ ‏مَرَّتْ بِكَلْبٍ عَلَى رَأْسِ رَكِيٍّ يَلْهَثُ قَدْ كَادَ يَقْتُلُهُ الْعَطَشُ ‏ ‏فَنَزَعَتْ ‏ ‏خُفَّهَا فَأَوْثَقَتْهُ بِخِمَارِهَا ‏ ‏فَنَزَعَتْ ‏ ‏لَهُ مِنْ الْمَاءِ فَغُفِرَ لَهَا بِذَلِكَ ‏","","",""],[10213,10213,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُسْلِمَيْنِ يَمُوتُ لَهُمَا ثَلَاثَةُ أَوْلَادٍ لَمْ ‏ ‏يَبْلُغُوا ‏ ‏الْحِنْثَ ‏ ‏إِلَّا أَدْخَلَهُمَا اللَّهُ ‏ ‏وَإِيَّاهُمْ ‏ ‏بِفَضْلِ رَحْمَتِهِ الْجَنَّةَ وَقَالَ يُقَالُ لَهُمْ ادْخُلُوا الْجَنَّةَ قَالَ فَيَقُولُونَ حَتَّى يَجِيءَ أَبَوَانَا قَالَ ثَلَاثَ مَرَّاتٍ فَيَقُولُونَ مِثْلَ ذَلِكَ فَيُقَالُ لَهُمْ ادْخُلُوا الْجَنَّةَ أَنْتُمْ وَأَبَوَاكُمْ ‏","","",""],[10214,10214,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ صَلَاتَيْنِ وَعَنْ لِبْسَتَيْنِ وَعَنْ بَيْعَتَيْنِ نَهَى عَنْ صَلَاةٍ بَعْدَ الْفَجْرِ حَتَّى تَطْلُعَ الشَّمْسُ وَعَنْ الصَّلَاةِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَعَنْ ‏ ‏اشْتِمَالِ ‏ ‏الصَّمَّاءِ ‏ ‏وَعَنْ ‏ ‏الِاحْتِبَاءِ ‏ ‏فِي ثَوْبٍ وَاحِدٍ ‏ ‏تُفْضِي بِفَرْجِكَ إِلَى السَّمَاءِ ‏","","",""],[10215,10215,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏زِيَادٌ ‏ ‏أَنَّ ‏ ‏ثَابِتًا ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ زَيْدٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَلِّمُ الرَّاكِبُ عَلَى الْمَاشِي وَالْمَاشِي عَلَى الْقَاعِدِ وَالْقَلِيلُ عَلَى الْكَثِيرِ ‏","","",""],[10216,10216,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حُبَيْبٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَلِّمُ الرَّاكِبُ عَلَى الْمَاشِي وَالْمَاشِي عَلَى الْقَاعِدِ وَقَالَ ‏ ‏بِبَغْدَادَ ‏ ‏وَالْقَلِيلُ عَلَى الْكَثِيرِ وَالصَّغِيرُ عَلَى الْكَبِيرِ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏بِبَغْدَادَ ‏ ‏وَالْقَلِيلُ عَلَى الْكَثِيرِ ‏","","",""],[10217,10217,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏قَالَ حَدَّثَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكُمْ بِالْحَبَّةِ السَّوْدَاءِ فَإِنَّهَا شِفَاءٌ مِنْ كُلِّ شَيْءٍ إِلَّا مِنْ ‏ ‏السَّامِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏الْمَوْتُ ‏","","",""],[10218,10218,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْكَرِيمِ بْنُ مَالِكٍ ‏ ‏أَنَّ ‏ ‏عُبَيْدَ اللَّهِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَمْرَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَمِّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُكْنَى بِكُنْيَتِهِ ‏","","",""],[10219,10219,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَقُّ الضِّيَافَةِ ثَلَاثَةُ أَيَّامٍ فَمَا ‏ ‏أَصَابَ ‏ ‏بَعْدَ ذَلِكَ فَهُوَ صَدَقَةٌ ‏","","",""],[10220,10220,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعَ أَحَدُكُمْ النِّدَاءَ وَالْإِنَاءُ عَلَى يَدِهِ فَلَا يَضَعْهُ حَتَّى يَقْضِيَ حَاجَتَهُ مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ وَزَادَ فِيهِ وَكَانَ الْمُؤَذِّنُ يُؤَذِّنُ إِذَا بَزَغَ الْفَجْرُ ‏","","",""],[10221,10221,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلصَّائِمِ فَرْحَتَانِ فَرْحَةٌ عِنْدَ إِفْطَارِهِ وَفَرْحَةٌ حِينَ يَلْقَى رَبَّهُ عَزَّ وَجَلَّ ‏","","",""],[10222,10222,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏يَأْجُوجَ ‏ ‏وَمَأْجُوجَ ‏ ‏لَيَحْفِرُونَ ‏ ‏السَّدَّ كُلَّ يَوْمٍ حَتَّى إِذَا كَادُوا يَرَوْنَ شُعَاعَ الشَّمْسِ قَالَ الَّذِي عَلَيْهِمْ ارْجِعُوا فَسَتَحْفِرُونَهُ غَدًا فَيَعُودُونَ إِلَيْهِ كَأَشَدِّ مَا كَانَ حَتَّى إِذَا بَلَغَتْ مُدَّتُهُمْ وَأَرَادَ ‏ ‏اللَّهُ عَزَّ وَجَلَّ أَنْ يَبْعَثَهُمْ إِلَى النَّاسِ حَفَرُوا حَتَّى إِذَا كَادُوا يَرَوْنَ شُعَاعَ الشَّمْسِ قَالَ الَّذِي عَلَيْهِمْ ارْجِعُوا فَسَتَحْفِرُونَهُ غَدًا إِنْ شَاءَ اللَّهُ ‏ ‏وَيَسْتَثْنِي ‏ ‏فَيَعُودُونَ إِلَيْهِ وَهُوَ كَهَيْئَتِهِ حِينَ تَرَكُوهُ فَيَحْفِرُونَهُ وَيَخْرُجُونَ عَلَى النَّاسِ فَيُنَشِّفُونَ الْمِيَاهَ وَيَتَحَصَّنَ النَّاسُ مِنْهُمْ فِي حُصُونِهِمْ فَيَرْمُونَ بِسِهَامِهِمْ إِلَى السَّمَاءِ فَتَرْجِعُ وَعَلَيْهَا كَهَيْئَةِ الدَّمِ فَيَقُولُونَ قَهَرْنَا أَهْلَ الْأَرْضِ وَعَلَوْنَا أَهْلَ السَّمَاءِ فَيَبْعَثُ اللَّهُ عَلَيْهِمْ ‏ ‏نَغَفًا ‏ ‏فِي أَقْفَائِهِمْ فَيَقْتُلُهُمْ بِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ إِنَّ دَوَابَّ الْأَرْضِ لَتَسْمَنُ شَكَرًا مِنْ لُحُومِهِمْ وَدِمَائِهِمْ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏يَأْجُوجَ ‏ ‏وَمَأْجُوجَ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ إِذَا بَلَغَتْ مُدَّتُهُمْ وَأَرَادَ اللَّهُ عَزَّ وَجَلَّ أَنْ يَبْعَثَهُمْ عَلَى النَّاسِ ‏","","",""],[10223,10223,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ صِيَامِ يَوْمَيْنِ يَوْمِ الْفِطْرِ وَيَوْمِ ‏ ‏النَّحْرِ ‏","","",""],[10224,10224,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلَا ‏ ‏يَرْفُثْ ‏ ‏وَلَا يَجْهَلْ وَلَا يُؤْذِي أَحَدًا فَإِنْ جَهِلَ عَلَيْهِ أَحَدٌ أَوْ آذَاهُ فَلْيَقُلْ إِنِّي صَائِمٌ ‏","","",""],[10225,10225,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَضْحَكُ مِنْ رَجُلَيْنِ يَقْتُلُ أَحَدُهُمَا الْآخَرَ فَيُدْخِلُهُمَا اللَّهُ عَزَّ وَجَلَّ الْجَنَّةَ قِيلَ كَيْفَ يَكُونُ ذَاكَ قَالَ يَكُونُ أَحَدُهُمَا كَافِرًا فَيَقْتُلُ الْآخَرَ ثُمَّ يُسْلِمُ فَيَغْزُو فِي سَبِيلِ اللَّهِ فَيُقْتَلُ ‏","","",""],[10226,10226,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنَا ‏ ‏زِيَادٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏أخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ وَمَنْ أَطَاعَ أَمِيرِي فَقَدْ أَطَاعَنِي وَمَنْ عَصَى أَمِيرِي فَقَدْ عَصَانِي ‏","","",""],[10227,10227,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَعَبْدِ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏الْمَعْنَى ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُمْطِرَ عَلَى ‏ ‏أَيُّوبَ ‏ ‏جَرَادٌ مِنْ ذَهَبٍ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فَرَاشٌ ‏ ‏فَجَعَلَ ‏ ‏يَلْتَقِطُهُ ‏ ‏فَقَالَ يَا ‏ ‏أَيُّوبُ ‏ ‏أَلَمْ أُوَسِّعْ عَلَيْكَ قَالَ يَا رَبِّ وَمَنْ يَشْبَعُ مِنْ رَحْمَتِكَ ‏ ‏أَوْ قَالَ مِنْ فَضْلِكَ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ بَلَى وَلَكِنْ لَا غِنًى بِي عَنْ فَضْلِكَ ‏","","",""],[10228,10228,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ عَلَى أَصْحَابِهِ وَهُمْ يَذْكُرُونَ ‏ ‏الْكَمْأَةَ ‏ ‏قَالُوا ‏ ‏تُرَاهَا جُدَرِيَّ الْأَرْضِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَمْأَةُ ‏ ‏مِنْ ‏ ‏الْمَنِّ ‏ ‏وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ وَالْعَجْوَةُ مِنْ الْجَنَّةِ وَهِيَ شِفَاءٌ مِنْ السُّمِّ ‏","","",""],[10229,10229,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا ‏ ‏بِالْأَعْمَالِ سِتًّا طُلُوعَ الشَّمْسِ مِنْ مَغْرِبِهَا ‏ ‏وَالدَّجَّالَ ‏ ‏وَالدُّخَانَ وَدَابَّةَ الْأَرْضِ ‏ ‏وَخُوَيْصَّةَ ‏ ‏أَحَدِكُمْ ‏ ‏وَأَمْرَ الْعَامَّةِ ‏","","",""],[10230,10230,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ أَبِي أَسِيدٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَتَتَّبِعُنَّ سَنَنَ مَنْ كَانَ قَبْلَكُمْ شِبْرًا بِشِبْرٍ وَذِرَاعًا بِذِرَاعٍ حَتَّى لَوْ دَخَلُوا جُحْرَ ضَبٍّ لَدَخَلْتُمُوهُ ‏","","",""],[10231,10231,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمًا وَهُوَ يُحَدِّثُ وَعِنْدَهُ رَجُلٌ مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏إِنَّ رَجُلًا مِنْ أَهْلِ الْجَنَّةِ اسْتَأْذَنَ رَبَّهُ عَزَّ وَجَلَّ فِي الزَّرْعِ فَقَالَ لَهُ رَبُّهُ عَزَّ وَجَلَّ أَلَسْتَ فِيمَا شِئْتَ قَالَ بَلَى وَلَكِنْ أُحِبُّ أَنْ أَزْرَعَ قَالَ فَبَذَرَ ‏ ‏فَبَادَرَ ‏ ‏الطَّرْفَ ‏ ‏نَبَاتُهُ وَاسْتِوَاؤُهُ وَاسْتِحْصَادُهُ فَكَانَ أَمْثَالَ الْجِبَالِ قَالَ فَيَقُولُ لَهُ رَبُّهُ عَزَّ وَجَلَّ ‏ ‏دُونَكَ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏فَإِنَّهُ لَا يُشْبِعُكَ شَيْءٌ قَالَ فَقَالَ الْأَعْرَابِيُّ وَاللَّهِ لَا تَجِدُهُ إِلَّا قُرَشِيًّا أَوْ أَنْصَارِيًّا فَإِنَّهُمْ أَصْحَابُ زَرْعٍ وَأَمَّا نَحْنُ فَلَسْنَا بِأَصْحَابِهِ قَالَ فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[10232,10232,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ آدَمَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏كَتَبَ ‏ ‏الْجُمُعَةَ عَلَى مَنْ كَانَ قَبْلَنَا فَاخْتَلَفَ النَّاسُ فِيهَا وَهَدَانَا اللَّهُ لَهَا فَالنَّاسُ لَنَا فِيهَا تَبَعٌ فَالْيَوْمُ لَنَا ‏ ‏وَلِلْيَهُودِ ‏ ‏غَدًا ‏ ‏وَلِلنَّصَارَى ‏ ‏بَعْدَ غَدٍ ‏ ‏لِلْيَهُودِ ‏ ‏يَوْمُ السَّبْتِ ‏ ‏وَلِلنَّصَارَى ‏ ‏يَوْمُ الْأَحَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏مَوْلَى ‏ ‏أُمِّ بُرْثُنٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَذَكَرَ مِثْلَهُ وَلَمْ يَذْكُرْ الْيَوْمُ لَنَا ‏","","",""],[10233,10233,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ أَبِي الْأَخْضَرِ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ يَوْمٍ طَلَعَتْ عَلَيْهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ فِيهِ خُلِقَ ‏ ‏آدَمُ ‏ ‏وَفِيهِ أُدْخِلَ الْجَنَّةَ وَفِيهِ أُخْرِجَ مِنْهَا ‏","","",""],[10234,10234,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَأَبِي عَبْدِ اللَّهِ الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى كُلِّ بَابِ مَسْجِدٍ يَوْمَ الْجُمُعَةِ مَلَائِكَةٌ يَكْتُبُونَ مَجِيءَ الرَّجُلِ فَإِذَا جَلَسَ الْإِمَامُ طُوِيَتْ الصُّحُفُ ‏ ‏فَالْمُهَجِّرُ ‏ ‏كَالْمُهْدِي ‏ ‏جَزُورًا ‏ ‏وَالَّذِي يَلِيهِ كَمُهْدِي الْبَقَرَةَ وَالَّذِي يَلِيهِ كَمُهْدِي الشَّاةَ وَالَّذِي يَلِيهِ كَمُهْدِي الدَّجَاجَةَ وَالَّذِي يَلِيهِ كَمُهْدِي الْبَيْضَةَ ‏","","",""],[10235,10235,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ أَبِي الْأَخْضَرِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ ‏ ‏أُسْرِيَ ‏ ‏بِي أُتِيتُ ‏ ‏بِقَدَحَيْنِ ‏ ‏قَدَحِ ‏ ‏لَبَنٍ وَقَدَحِ خَمْرٍ فَنَظَرْتُ إِلَيْهِمَا فَأَخَذْتُ اللَّبَنَ فَقَالَ ‏ ‏جِبْرِيلُ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي هَدَاكَ لِلْفِطْرَةِ لَوْ أَخَذْتَ الْخَمْرَ ‏ ‏غَوَتْ ‏ ‏أُمَّتُكَ ‏","","",""],[10236,10236,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّهُ حَدَّثَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏لَمْ يَرْفَعْهُ قَالَ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏حَرَّمَ اللَّهُ عَلَيْهِمْ الشُّحُومَ فَبَاعُوهُ وَأَكَلُوا ثَمَنَهُ ‏","","",""],[10237,10237,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا تَنَافَسُوا وَلَا ‏ ‏تَحَاسَدُوا ‏ ‏وَلَا تَبَاغَضُوا وَلَا ‏ ‏يَسْتَامُ ‏ ‏الرَّجُلُ عَلَى ‏ ‏سَوْمِ ‏ ‏أَخِيهِ وَلَا يَبِعْ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏دَعُوا النَّاسَ يَرْزُقُ اللَّهُ بَعْضَهُمْ مِنْ بَعْضٍ وَلَا تَشْتَرِطْ امْرَأَةٌ طَلَاقَ أُخْتِهَا ‏","","",""],[10238,10238,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ لَا تَدْخُلُوا الْجَنَّةَ حَتَّى تُؤْمِنُوا وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا قَالَ إِنْ شِئْتُمْ دَلَلْتُكُمْ عَلَى مَا إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ أَفْشُوا السَّلَامَ بَيْنَكُمْ ‏","","",""],[10239,10239,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَأَلَكُمْ بِاللَّهِ فَأَعْطُوهُ وَمَنْ دَعَاكُمْ فَأَجِيبُوهُ وَلَوْ أُهْدِيَ إِلَيَّ ‏ ‏كُرَاعٌ ‏ ‏لَقَبِلْتُ وَلَوْ دُعِيتُ إِلَى ‏ ‏كُرَاعٍ ‏ ‏لَأَجَبْتُ ‏","","",""],[10240,10240,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ أَهْلِ النَّارِ يَرَى مَقْعَدَهُ مِنْ الْجَنَّةِ فَيَقُولُ لَوْ أَنَّ اللَّهَ هَدَانِي فَيَكُونُ عَلَيْهِمْ حَسْرَةً قَالَ وَكُلُّ أَهْلِ الْجَنَّةِ يَرَى مَقْعَدَهُ مِنْ النَّارِ فَيَقُولُ لَوْلَا أَنَّ اللَّهَ هَدَانِي قَالَ فَيَكُونُ لَهُ شُكْرًا ‏","","",""],[10241,10241,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ جُرِحَ جُرْحًا فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ جَاءَ يَوْمَ الْقِيَامَةِ كَهَيْئَتِهِ لَوْنُهُ لَوْنُ الدَّمِ وَرِيحُهُ رِيحُ الْمِسْكِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏أَيْضًا ‏ ‏يَعْنِي ‏ ‏أَسْوَدَ ‏","","",""],[10242,10242,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ الْفُقَرَاءُ الْجَنَّةَ قَبْلَ الْأَغْنِيَاءِ بِنِصْفِ يَوْمٍ وَهُوَ خَمْسُ مِائَةِ عَامٍ ‏","","",""],[10243,10243,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَقْبَلَ ‏ ‏سَعْدٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَآهُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي وَجْهِ ‏ ‏سَعْدٍ ‏ ‏لَخَبَرًا قَالَ قُتِلَ ‏ ‏كِسْرَى ‏ ‏قَالَ يَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏كِسْرَى ‏ ‏إِنَّ أَوَّلَ النَّاسِ هَلَاكًا ‏ ‏الْعَرَبُ ‏ ‏ثُمَّ أَهْلُ ‏ ‏فَارِسَ ‏","","",""],[10244,10244,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُؤْتَى بِالْمَوْتِ يَوْمَ الْقِيَامَةِ كَبْشًا فَيُقَالُ يَا أَهْلَ الْجَنَّةِ تَعْرِفُونَ هَذَا فَيَطَّلِعُونَ خَائِفِينَ قَالَ فَيَقُولُونَ نَعَمْ قَالَ ثُمَّ يُنَادَ أَهْلُ النَّارِ تَعْرِفُونَ هَذَا فَيَقُولُونَ نَعَمْ فَيُذْبَحُ ثُمَّ يُقَالُ خُلُودٌ فِي الْجَنَّةِ وَخُلُودٌ فِي النَّارِ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏مِثْلَهُ إِلَّا أَنَّهُ زَادَ فِيهِ يُؤْتَى عَلَى الصِّرَاطِ فَيُذْبَحُ ‏","","",""],[10245,10245,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ رَجُلٌ عَلَى أَهْلِهِ فَلَمَّا رَأَى مَا بِهِمْ مِنْ ‏ ‏الْحَاجَةِ ‏ ‏خَرَجَ إِلَى الْبَرِيَّةِ فَلَمَّا رَأَتْ امْرَأَتُهُ قَامَتْ إِلَى ‏ ‏الرَّحَى ‏ ‏فَوَضَعَتْهَا وَإِلَى ‏ ‏التَّنُّورِ ‏ ‏فَسَجَرَتْهُ ‏ ‏ثُمَّ قَالَتْ اللَّهُمَّ ارْزُقْنَا فَنَظَرَتْ فَإِذَا ‏ ‏الْجَفْنَةُ ‏ ‏قَدْ امْتَلَأَتْ قَالَ وَذَهَبَتْ إِلَى ‏ ‏التَّنُّورِ ‏ ‏فَوَجَدَتْهُ مُمْتَلِئًا قَالَ فَرَجَعَ الزَّوْجُ قَالَ أَصَبْتُمْ بَعْدِي شَيْئًا قَالَتْ امْرَأَتُهُ نَعَمْ مِنْ رَبِّنَا قَامَ إِلَى ‏ ‏الرَّحَى ‏ ‏فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَمَا إِنَّهُ لَوْ لَمْ يَرْفَعْهَا لَمْ تَزَلْ تَدُورُ إِلَى يَوْمِ الْقِيَامَةِ شَهِدْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ وَاللَّهِ لَأَنْ يَأْتِيَ أَحَدُكُمْ صَبِيرًا ثُمَّ يَحْمِلَهُ يَبِيعَهُ فَيَسْتَعِفَّ مِنْهُ خَيْرٌ لَهُ مِنْ أَنْ يَأْتِيَ رَجُلًا يَسْأَلُهُ ‏","","",""],[10246,10246,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏كَامِلٌ ‏ ‏وَأَبُو الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏كَامِلٌ أَبُو الْعَلَاءِ ‏ ‏قَالَ ‏ ‏أَسْوَدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِشَاءَ ‏ ‏فَإِذَا سَجَدَ وَثَبَ ‏ ‏الْحَسَنُ ‏ ‏وَالْحُسَيْنُ ‏ ‏عَلَى ظَهْرِهِ فَإِذَا رَفَعَ رَأْسَهُ أَخَذَهُمَا بِيَدِهِ مِنْ خَلْفِهِ أَخْذًا رَفِيقًا وَيَضَعُهُمَا عَلَى الْأَرْضِ فَإِذَا عَادَ عَادَا حَتَّى إِذَا قَضَى صَلَاتَهُ أَقْعَدَهُمَا عَلَى فَخِذَيْهِ قَالَ فَقُمْتُ إِلَيْهِ فَقُلْتُ يَا رَسُولَ اللَّهِ أَرُدُّهُمَا فَبَرَقَتْ بَرْقَةٌ فَقَالَ لَهُمَا الْحَقَا بِأُمِّكُمَا قَالَ فَمَكَثَ ضَوْءُهَا حَتَّى دَخَلَا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏بِإِسْنَادِهِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏حَتَّى دَخَلَا عَلَى أُمِّهِمَا ‏","","",""],[10247,10247,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ بْنِ عَلِيٍّ الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيُهِلَّنَّ ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏بِفَجِّ الرَّوْحَاءِ ‏ ‏بِالْحَجِّ أَوْ الْعُمْرَةِ أَوْ لَيُثَنِّيَهُمَا جَمِيعًا ‏","","",""],[10248,10248,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏وَحُسَيْنُ بْنُ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تَقَدَّمُوا ‏ ‏قَبْلَ رَمَضَانَ بِصَوْمِ يَوْمٍ أَوْ يَوْمَيْنِ إِلَّا رَجُلًا كَانَ يَصُومُ صِيَامًا فَيَصِلُهُ بِهِ ‏","","",""],[10249,10249,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ فِي سَفَرٍ فَلَمَّا نَزَلُوا أَرْسَلُوا إِلَيْهِ وَهُوَ ‏ ‏يُصَلِّي فَقَالَ إِنِّي صَائِمٌ فَلَمَّا وَضَعُوا الطَّعَامَ وَكَادَ أَنْ يَفْرَغُوا جَاءَ فَقَالُوا هَلُمَّ فَكُلْ فَأَكَلَ فَنَظَرَ الْقَوْمُ إِلَى الرَّسُولِ فَقَالَ مَا تَنْظُرُونَ فَقَالَ وَاللَّهِ لَقَدْ قَالَ إِنِّي صَائِمٌ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏صَدَقَ وَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَوْمُ شَهْرِ الصَّبْرِ وَثَلَاثَةُ أَيَّامٍ مِنْ كُلِّ شَهْرٍ صَوْمُ الدَّهْرِ كُلِّهِ فَقَدْ صُمْتُ ثَلَاثَةَ أَيَّامٍ مِنْ أَوَّلِ الشَّهْرِ فَأَنَا مُفْطِرٌ فِي تَخْفِيفِ اللَّهِ صَائِمٌ فِي تَضْعِيفِ اللَّهِ ‏","","",""],[10250,10250,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏عَبْدَ اللَّهِ بْنَ حُذَافَةَ ‏ ‏يَطُوفُ فِي ‏ ‏مِنًى ‏ ‏أَنْ لَا تَصُومُوا هَذِهِ الْأَيَّامَ فَإِنَّهَا أَيَّامُ أَكْلٍ وَشُرْبٍ وَذِكْرِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[10251,10251,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏وَهِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ ‏ ‏أَوْ شَرِبَ نَاسِيًا وَهُوَ صَائِمٌ فَلْيُتِمَّ صَوْمَهُ فَإِنَّمَا أَطْعَمَهُ اللَّهُ وَسَقَاهُ ‏","","",""],[10252,10252,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤَذِّنُ مُؤْتَمَنٌ وَالْإِمَامُ ضَامِنٌ اللَّهُمَّ أَرْشِدْ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِينَ ‏","","",""],[10253,10253,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يُنْبَذَ ‏ ‏فِي ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[10254,10254,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏أَبِي الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ مِنْ دُعَائِهِ ‏ ‏اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَإِسْرَافِي وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ ‏","","",""],[10255,10255,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَتَمَنَّى أَحَدُكُمْ الْمَوْتَ إِمَّا مُسِيءٌ فَيَسْتَغْفِرُ أَوْ مُحْسِنٌ فَيَزْدَادُ ‏","","",""],[10256,10256,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏بَلَغَنِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلَّهِ عَزَّ وَجَلَّ مِائَةُ رَحْمَةٍ وَإِنَّهُ قَسَمَ رَحْمَةً وَاحِدَةً بَيْنَ أَهْلِ الْأَرْضِ فَوَسِعَتْهُمْ إِلَى آجَالِهِمْ وَذَخَرَ تِسْعَةً وَتِسْعِينَ رَحْمَةً لِأَوْلِيَائِهِ وَاللَّهُ عَزَّ وَجَلَّ قَابِضٌ تِلْكَ الرَّحْمَةَ الَّتِي قَسَمَهَا بَيْنَ أَهْلِ الْأَرْضِ إِلَى التِّسْعَةِ وَالتِّسْعِينَ فَيُكَمِّلُهَا مِائَةَ رَحْمَةٍ لِأَوْلِيَائِهِ يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏وَحَدَّثَنِي ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏مُحَمَّدُ بْنُ سِيرِينَ ‏ ‏وَخِلَاسٌ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ ذَلِكَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[10257,10257,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُقَبِّلُ ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏فَقَالَ ‏ ‏الْأَقْرَعُ بْنُ حَابِسٍ ‏ ‏إِنَّ لِي عَشَرَةً مِنْ الْوَلَدِ مَا قَبَّلْتُ مِنْهُمْ أَحَدًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَا يَرْحَمُ لَا يُرْحَمُ ‏","","",""],[10258,10258,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَحَبَّ اللَّهُ الْعَبْدَ نَادَى ‏ ‏جِبْرِيلَ ‏ ‏إِنَّ اللَّهَ قَدْ أَحَبَّ فُلَانًا فَأَحِبُّوهُ فَيُحِبُّهُ ‏ ‏جِبْرِيلُ ‏ ‏ثُمَّ يُنَادِي ‏ ‏جِبْرِيلُ ‏ ‏فِي أَهْلِ السَّمَاءِ إِنَّ اللَّهَ قَدْ أَحَبَّ فُلَانًا فَأَحِبُّوهُ فَيُحِبُّهُ أَهْلُ السَّمَاءِ ثُمَّ يُوضَعُ لَهُ الْقَبُولُ فِي أَهْلِ الْأَرْضِ ‏","","",""],[10259,10259,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏دَاوُدَ بْنَ فَرَاهِيجَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا زَالَ ‏ ‏جِبْرِيلُ ‏ ‏يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ ‏","","",""],[10260,10260,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏نَفَّسَ ‏ ‏عَنْ أَخِيهِ الْمُسْلِمِ ‏ ‏كُرْبَةً ‏ ‏مِنْ ‏ ‏كُرَبِ ‏ ‏الدُّنْيَا ‏ ‏نَفَّسَ ‏ ‏اللَّهُ عَنْهُ ‏ ‏كُرْبَةً ‏ ‏مِنْ ‏ ‏كُرَبِ ‏ ‏الْآخِرَةِ وَمَنْ سَتَرَ عَنْ أَخِيهِ الْمُسْلِمِ سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَةِ وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ ‏","","",""],[10261,10261,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يُنْجِي أَحَدَكُمْ عَمَلُهُ قَالُوا وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ مِنْهُ بِرَحْمَةٍ ‏ ‏فَسَدِّدُوا ‏ ‏وَقَارِبُوا ‏ ‏وَاغْدُوا ‏ ‏وَرُوحُوا ‏ ‏وَشَيْءٌ مِنْ ‏ ‏الدُّلْجَةِ ‏ ‏وَالْقَصْدَ ‏ ‏الْقَصْدَ ‏ ‏تَبْلُغُوا ‏","","",""],[10262,10262,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخِلَاسٌ ‏ ‏وَمُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي هَذِهِ ‏ ‏الْآيَةِ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَكُونُوا كَالَّذِينَ آذَوْا ‏ ‏مُوسَى ‏ ‏فَبَرَّأَهُ اللَّهُ مِمَّا قَالُوا ‏} ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏مُوسَى ‏ ‏كَانَ رَجُلًا حَيِيًّا ‏ ‏سِتِّيرًا لَا يَكَادُ ‏ ‏يُرِي مِنْ جِلْدِهِ شَيْئًا اسْتِحْيَاءً مِنْهُ قَالَ فَآذَاهُ مَنْ آذَاهُ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏قَالُوا مَا يَتَسَتَّرُ هَذَا التَّسَتُّرَ إِلَّا مِنْ عَيْبٍ بِجِلْدِهِ إِمَّا بَرَصًا وَإِمَّا ‏ ‏أُدْرَةً ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏مَرَّةً ‏ ‏أُدْرَةً ‏ ‏وَإِمَّا ‏ ‏آفَةً ‏ ‏وَإِنَّ اللَّهَ عَزَّ وَجَلَّ أَرَادَ أَنْ يُبَرِّئَهُ مِمَّا قَالُوا وَإِنَّ ‏ ‏مُوسَى ‏ ‏خَلَا يَوْمًا فَوَضَعَ ثَوْبَهُ عَلَى حَجَرٍ ثُمَّ اغْتَسَلَ فَلَمَّا فَرَغَ أَقْبَلَ إِلَى ثَوْبِهِ لِيَأْخُذَهُ وَإِنَّ الْحَجَرَ عَدَا بِثَوْبِهِ فَأَخَذَ ‏ ‏مُوسَى ‏ ‏عَصَاهُ وَطَلَبَ الْحَجَرَ وَجَعَلَ يَقُولُ ثَوْبِي حَجَرُ ثَوْبِي حَجَرُ حَتَّى انْتَهَى إِلَى مَلَإٍ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَرَأَوْهُ عُرْيَانًا كَأَحْسَنِ الرِّجَالِ خَلْقًا وَأَبْرَأَهُ مِمَّا كَانُوا يَقُولُونَ لَهُ وَقَامَ الْحَجَرُ فَأَخَذَ ثَوْبَهُ ‏ ‏وَطَفِقَ ‏ ‏بِالْحَجَرِ ضَرْبًا بِعَصَاهُ قَالَ فَوَاللَّهِ إِنَّ فِي الْحَجَرِ ‏ ‏لَنَدَبًا ‏ ‏مِنْ أَثَرِ ضَرْبِهِ ثَلَاثًا أَوْ أَرْبَعًا أَوْ خَمْسًا ‏","","",""],[10263,10263,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ ذَرٍّ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ يَقُولُ وَاللَّهِ إِنْ كُنْتُ لَأَعْتَمِدُ بِكَبِدِي عَلَى الْأَرْضِ مِنْ الْجُوعِ وَإِنْ كُنْتُ لَأَشُدُّ الْحَجَرَ عَلَى بَطْنِي مِنْ الْجُوعِ وَلَقَدْ قَعَدْتُ يَوْمًا عَلَى طَرِيقِهِمْ الَّذِي يَخْرُجُونَ مِنْهُ فَمَرَّ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَسَأَلْتُهُ عَنْ آيَةٍ مِنْ كِتَابِ اللَّهِ عَزَّ وَجَلَّ مَا سَأَلْتُهُ إِلَّا لِيَسْتَتْبِعَنِي فَلَمْ يَفْعَلْ فَمَرَّ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَسَأَلْتُهُ عَنْ آيَةٍ مِنْ كِتَابِ اللَّهِ مَا سَأَلْتُهُ إِلَّا لِيَسْتَتْبِعَنِي فَلَمْ يَفْعَلْ فَمَرَّ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَرَفَ مَا فِي وَجْهِي وَمَا فِي نَفْسِي فَقَالَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَقُلْتُ لَهُ لَبَّيْكَ يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏الْحَقْ وَاسْتَأْذَنْتُ فَأَذِنَ لِي فَوَجَدْتُ لَبَنًا فِي قَدَحٍ فَقَالَ مِنْ أَيْنَ لَكُمْ هَذَا اللَّبَنُ فَقَالُوا أَهْدَاهُ لَنَا فُلَانٌ أَوْ آلُ فُلَانٍ قَالَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قُلْتُ لَبَّيْكَ يَا رَسُولَ اللَّهِ قَالَ انْطَلِقْ إِلَى ‏ ‏أَهْلِ الصُّفَّةِ ‏ ‏فَادْعُهُمْ لِي قَالَ ‏ ‏وَأَهْلُ الصُّفَّةِ ‏ ‏أَضْيَافُ الْإِسْلَامِ لَمْ يَأْوُوا إِلَى أَهْلٍ وَلَا مَالٍ إِذَا جَاءَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَدِيَّةٌ أَصَابَ مِنْهَا وَبَعَثَ إِلَيْهِمْ مِنْهَا قَالَ وَأَحْزَنَنِي ذَلِكَ وَكُنْتُ أَرْجُو أَنْ أُصِيبَ مِنْ اللَّبَنِ شَرْبَةً أَتَقَوَّى بِهَا بَقِيَّةَ يَوْمِي وَلَيْلَتِي فَقُلْتُ أَنَا الرَّسُولُ فَإِذَا جَاءَ الْقَوْمُ كُنْتُ أَنَا الَّذِي أُعْطِيهِمْ فَقُلْتُ مَا يَبْقَى لِي مِنْ هَذَا اللَّبَنِ وَلَمْ يَكُنْ مِنْ طَاعَةِ اللَّهِ وَطَاعَةِ رَسُولِهِ بُدٌّ فَانْطَلَقْتُ فَدَعَوْتُهُمْ فَأَقْبَلُوا فَاسْتَأْذَنُوا فَأَذِنَ لَهُمْ فَأَخَذُوا مَجَالِسَهُمْ مِنْ الْبَيْتِ ثُمَّ قَالَ ‏ ‏أَبَا هِرٍّ ‏ ‏خُذْ فَأَعْطِهِمْ فَأَخَذْتُ الْقَدَحَ فَجَعَلْتُ أُعْطِيهِمْ فَيَأْخُذُ الرَّجُلُ الْقَدَحَ فَيَشْرَبُ حَتَّى ‏ ‏يَرْوَى ثُمَّ يَرُدُّ الْقَدَحَ فَأُعْطِيهِ الْآخَرَ فَيَشْرَبُ حَتَّى ‏ ‏يَرْوَى ثُمَّ يَرُدُّ الْقَدَحَ حَتَّى أَتَيْتُ عَلَى آخِرِهِمْ وَدَفَعْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ الْقَدَحَ فَوَضَعَهُ فِي يَدِهِ وَبَقِيَ فِيهِ ‏ ‏فَضْلَةٌ ‏ ‏ثُمَّ رَفَعَ رَأْسَهُ فَنَظَرَ إِلَيَّ وَتَبَسَّمَ فَقَالَ ‏ ‏أَبَا هِرٍّ ‏ ‏قُلْتُ لَبَّيْكَ يَا رَسُولَ اللَّهِ قَالَ بَقِيتُ أَنَا وَأَنْتَ فَقُلْتُ صَدَقْتَ يَا رَسُولَ اللَّهِ قَالَ فَاقْعُدْ فَاشْرَبْ قَالَ فَقَعَدْتُ فَشَرِبْتُ ثُمَّ قَالَ ‏ ‏لِيَ اشْرَبْ فَشَرِبْتُ فَمَا زَالَ يَقُولُ ‏ ‏لِيَ اشْرَبْ فَأَشْرَبُ حَتَّى قُلْتُ لَا وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَجِدُ لَهَا فِيَّ مَسْلَكًا قَالَ نَاوِلْنِي الْقَدَحَ فَرَدَدْتُ إِلَيْهِ الْقَدَحَ فَشَرِبَ مِنْ الْفَضْلَةِ ‏","","",""],[10264,10264,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا جَلَسَ قَوْمٌ مَجْلِسًا فَتَفَرَّقُوا عَنْ غَيْرِ ذِكْرٍ إِلَّا تَفَرَّقُوا عَنْ مِثْلِ جِيفَةِ حِمَارٍ وَكَانَ ذَلِكَ الْمَجْلِسُ عَلَيْهِمْ حَسْرَةً يَوْمَ الْقِيَامَةِ ‏","","",""],[10265,10265,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ عَاصِمِ بْنِ سُفْيَانَ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَوْفَقَ الدُّعَاءِ أَنْ يَقُولَ الرَّجُلُ ‏ ‏اللَّهُمَّ أَنْتَ رَبِّي وَأَنَا عَبْدُكَ ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي يَا رَبِّ فَاغْفِرْ لِي ذَنْبِي إِنَّكَ أَنْتَ رَبِّي إِنَّهُ لَا يَغْفِرُ الذَّنْبَ إِلَّا أَنْتَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي حُسَيْنٍ الْمَكِّيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[10266,10266,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَالَ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ ‏ ‏حُطَّتْ ‏ ‏خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ ‏ ‏زَبَدِ ‏ ‏الْبَحْرِ ‏","","",""],[10267,10267,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي بِي وَأَنَا مَعَهُ حَيْثُ يَذْكُرُنِي ‏","","",""],[10268,10268,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏إِنَّ لِلَّهِ عَزَّ وَجَلَّ تِسْعَةً وَتِسْعِينَ اسْمًا مِائَةً غَيْرَ وَاحِدٍ مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[10269,10269,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏وَعُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏أَفْطَرَ فِي رَمَضَانَ ‏ ‏فَأَمَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُكَفِّرَ بِعِتْقِ رَقَبَةٍ أَوْ صِيَامِ شَهْرَيْنِ أَوْ إِطْعَامِ سِتِّينَ مِسْكِينًا قَالَ لَا أَجِدُ فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَقٍ ‏ ‏مِنْ تَمْرٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذْ هَذَا فَتَصَدَّقْ بِهِ قَالَ يَا رَسُولَ اللَّهِ مَا أَجِدُ أَحْوَجَ مِنِّي فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى بَدَتْ أَنْيَابُهُ قَالَ خُذْهَا ‏","","",""],[10270,10270,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏أَعْرَابِيًّا ‏ ‏جَاءَ يَلْطِمُ وَجْهَهُ وَيَنْتِفُ شَعَرَهُ وَيَقُولُ مَا ‏ ‏أُرَانِي إِلَّا قَدْ هَلَكْتُ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا أَهْلَكَكَ قَالَ ‏ ‏أَصَبْتُ ‏ ‏أَهْلِي ‏ ‏فِي رَمَضَانَ قَالَ ‏ ‏أَتَسْتَطِيعُ أَنْ تُعْتِقَ رَقَبَةً قَالَ لَا قَالَ أَتَسْتَطِيعُ أَنْ تَصُومَ شَهْرَيْنِ مُتَتَابِعَيْنِ قَالَ لَا قَالَ أَتَسْتَطِيعُ أَنْ تُطْعِمَ سِتِّينَ مِسْكِينًا قَالَ لَا وَذَكَرَ ‏ ‏الْحَاجَةَ ‏ ‏قَالَ فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِزِنْبِيلٍ ‏ ‏وَهُوَ ‏ ‏الْمِكْتَلُ ‏ ‏فِيهِ خَمْسَةَ عَشَرَ ‏ ‏صَاعًا ‏ ‏أَحْسَبُهُ تَمْرًا قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْنَ الرَّجُلُ قَالَ أَطْعِمْ هَذَا قَالَ يَا رَسُولَ اللَّهِ مَا بَيْنَ ‏ ‏لَابَتَيْهَا ‏ ‏أَحَدٌ أَحْوَجُ مِنَّا أَهْلُ بَيْتٍ قَالَ فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى بَدَتْ أَنْيَابُهُ قَالَ أَطْعِمْ أَهْلَكَ ‏","","",""],[10271,10271,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَسِمُ ‏ ‏الرَّجُلُ عَلَى ‏ ‏سَوْمِ ‏ ‏أَخِيهِ وَلَا يَخْطُبُ عَلَى خِطْبَةِ أَخِيهِ وَلَا تُنْكَحُ الْمَرْأَةُ عَلَى عَمَّتِهَا وَلَا عَلَى خَالَتِهَا وَلَا تَسْأَلُ الْمَرْأَةُ طَلَاقَ أُخْتِهَا لِتَكْتَفِئَ ‏ ‏صَحْفَتَهَا ‏ ‏فَإِنَّمَا لَهَا مَا ‏ ‏كَتَبَ ‏ ‏اللَّهُ لَهَا ‏","","",""],[10272,10272,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُجْمَعُ بَيْنَ الْمَرْأَةِ وَعَمَّتِهَا وَلَا بَيْنَ الْمَرْأَةِ وَخَالَتِهَا ‏","","",""],[10273,10273,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا وَالصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ ‏ ‏وَلَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ ‏","","",""],[10274,10274,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ الزَّيَّاتِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ عَمَلِ ابْنِ ‏ ‏آدَمَ ‏ ‏لَهُ إِلَّا الصِّيَامَ فَهُوَ لِي وَأَنَا أَجْزِي بِهِ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ مِنْ رِيحِ الْمِسْكِ وَالصِّيَامُ ‏ ‏جُنَّةٌ ‏ ‏وَلِلصَّائِمِ فَرْحَتَانِ يَفْرَحُهُمَا إِذَا أَفْطَرَ فَرِحَ وَإِذَا لَقِيَ رَبَّهُ عَزَّ وَجَلَّ فَرِحَ بِصَوْمِهِ ‏","","",""],[10275,10275,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ ‏ ‏يَذَرُ ‏ ‏طَعَامَهُ وَشَرَابَهُ وَشَهْوَتَهُ مِنْ أَجْلِي فَالصِّيَامُ لِي وَأَنَا أَجْزِي بِهِ كُلُّ حَسَنَةٍ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِ مِائَةِ ضِعْفٍ إِلَّا الصِّيَامَ فَهُوَ لِي وَأَنَا أَجْزِي بِهِ ‏","","",""],[10276,10276,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْوِصَالِ ‏ ‏فَقَالَ رَجُلٌ مِنْ الْمُسْلِمِينَ إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ لَسْتُمْ مِثْلِي إِنِّي أَبِيتُ يُطْعِمُنِي رَبِّي وَيَسْقِينِي فَلَمَّا أَبَوْا أَنْ يَنْتَهُوا عَنْ ‏ ‏الْوِصَالِ ‏ ‏وَاصَلَ بِهِمْ يَوْمًا ثُمَّ يَوْمًا ثُمَّ رُئِيَ الْهِلَالُ فَقَالَ لَوْ تَأَخَّرَ لَزِدْتُكُمْ ‏ ‏كَالْمُنَكِّلِ ‏","","",""],[10277,10277,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏التَّثَاؤُبُ مِنْ الشَّيْطَانِ فَأَيُّكُمْ تَثَاءَبَ فَلْيَكْتُمْ مَا اسْتَطَاعَ ‏","","",""],[10278,10278,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ مَعَ الْوُضُوءِ ‏","","",""],[10279,10279,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتَ الرَّجُلَ يَقُولُ هَلَكَ النَّاسُ فَهُوَ ‏ ‏أَهْلَكُهُمْ ‏","","",""],[10280,10280,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَطَاءَ بْنَ يَسَارٍ ‏ ‏يَقُولُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا صَلَاةَ إِلَّا الْمَكْتُوبَةَ ‏","","",""],[10281,10281,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَيْنَمَا رَجُلٌ يَمْشِي بِطَرِيقٍ اشْتَدَّ عَلَيْهِ الْعَطَشُ فَوَجَدَ بِئْرًا فَنَزَلَ فِيهَا فَشَرِبَ ثُمَّ خَرَجَ فَإِذَا كَلْبٌ يَلْهَثُ يَأْكُلُ ‏ ‏الثَّرَى ‏ ‏مِنْ الْعَطَشِ فَقَالَ الرَّجُلُ لَقَدْ بَلَغَ هَذَا الْكَلْبَ مِنْ الْعَطَشِ مِثْلُ الَّذِي بَلَغَنِي فَنَزَلَ الْبِئْرَ فَمَلَأَ خُفَّهُ ثُمَّ أَمْسَكَهُ ‏ ‏بِفِيهِ ‏ ‏حَتَّى ‏ ‏رَقِيَ ‏ ‏فَسَقَى الْكَلْبَ فَشَكَرَ اللَّهُ عَزَّ وَجَلَّ لَهُ فَغَفَرَ لَهُ فَقِيلَ يَا رَسُولَ اللَّهِ إِنَّ لَنَا فِي الْبَهَائِمِ لَأَجْرًا فَقَالَ ‏ ‏فِي كُلِّ ذَاتِ كَبِدٍ رَطْبَةٍ أَجْرٌ ‏","","",""],[10282,10282,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ ‏ ‏مِنْ شَرِّ النَّاسِ ذَا الْوَجْهَيْنِ الَّذِي يَأْتِي هَؤُلَاءِ بِوَجْهٍ وَهَؤُلَاءِ بِوَجْهٍ ‏","","",""],[10283,10283,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ وَالظَّنَّ فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ وَلَا ‏ ‏تَجَسَّسُوا ‏ ‏وَلَا ‏ ‏تَحَسَّسُوا ‏ ‏وَلَا تَنَافَسُوا وَلَا تَحَاسَدُوا وَلَا تَبَاغَضُوا وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[10284,10284,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ الشَّدِيدُ ‏ ‏بِالصُّرَعَةِ ‏ ‏وَلَكِنَّ الشَّدِيدَ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ ‏","","",""],[10285,10285,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَلَاءَ بْنَ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمُسْتَبَّانِ مَا قَالَا عَلَى الْبَادِئِ حَتَّى يَعْتَدِيَ الْمَظْلُومُ ‏","","",""],[10286,10286,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي وَأَنَا مَعَهُ حِينَ يَذْكُرُنِي ‏","","",""],[10287,10287,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَرُونِي ‏ ‏مَا تَرَكْتُكُمْ فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِسُؤَالِهِمْ وَاخْتِلَافِهِمْ عَلَى أَنْبِيَائِهِمْ ‏","","",""],[10288,10288,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ شَاةً طُبِخَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطِنِي الذِّرَاعَ فَنَاوَلَهَا إِيَّاهُ فَقَالَ أَعْطِنِي الذِّرَاعَ فَنَاوَلَهَا إِيَّاهُ ثُمَّ قَالَ أَعْطِنِي الذِّرَاعَ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّمَا لِلشَّاةِ ذِرَاعَانِ قَالَ ‏ ‏أَمَا إِنَّكَ لَوْ الْتَمَسْتَهَا لَوَجَدْتَهَا ‏","","",""],[10289,10289,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ يُحِبُّ الْعُطَاسَ وَيَكْرَهُ التَّثَاؤُبَ فَإِذَا تَثَاءَبَ أَحَدُكُمْ فَقَالَ ‏ ‏هَاهْ فَإِنَّ ذَلِكَ شَيْطَانٌ يَضْحَكُ مِنْ جَوْفِهِ ‏","","",""],[10290,10290,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ الصَّوَّافُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثُ دَعَوَاتٍ مُسْتَجَابَاتٌ لَا شَكَّ فِيهِنَّ دَعْوَةُ الْوَالِدِ عَلَى وَلَدِهِ وَدَعْوَةُ الْمَظْلُومِ وَدَعْوَةُ الْمُسَافِرِ ‏","","",""],[10291,10291,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَمْرُ فِي هَاتَيْنِ ‏ ‏الشَّجَرَتَيْنِ النَّخْلَةِ وَالْعِنَبَةِ ‏","","",""],[10292,10292,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَمْرُ فِي هَاتَيْنِ الشَّجَرَتَيْنِ النَّخْلَةِ وَالْعِنَبَةِ ‏","","",""],[10293,10293,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ يَزِيدَ بْنِ فَرُّوخَ الضَّمْرِيِّ الْمَدَنِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يَقُولُ أَشْهَدُ لَسَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحْلِفُ عِنْدَ هَذَا الْمِنْبَرِ عَبْدٌ وَلَا أَمَةٌ عَلَى يَمِينٍ آثِمَةٍ وَلَوْ عَلَى سِوَاكٍ رَطْبٍ إِلَّا وَجَبَتْ لَهُ النَّارُ ‏","","",""],[10294,10294,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏قَبِيصَةُ بْنُ ذُؤَيْبٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُجْمَعَ بَيْنَ الْمَرْأَةِ وَعَمَّتِهَا وَبَيْنَ الْمَرْأَةِ وَخَالَتِهَا ‏","","",""],[10295,10295,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ مُغِيثٍ ‏ ‏أَوْ ‏ ‏مُعَتِّبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ مَاذَا رَدَّ إِلَيْكَ رَبُّكَ عَزَّ وَجَلَّ فِي الشَّفَاعَةِ قَالَ لَقَدْ ‏ ‏ظَنَنْتُ لَتَكُونَنَّ أَوَّلَ مَنْ سَأَلَنِي مِمَّا رَأَيْتُ مِنْ حِرْصِكَ عَلَى الْعِلْمِ شَفَاعَتِي لِمَنْ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ مُخْلِصًا يُصَدِّقُ قَلْبُهُ لِسَانَهُ وَلِسَانُهُ قَلْبَهُ ‏","","",""],[10296,10296,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الزُّرَقِىِّ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَخَذَتْ النَّاسَ الرِّيحُ بِطَرِيقِ ‏ ‏مَكَّةَ ‏ ‏فَاشْتَدَّتْ عَلَيْهِمْ فَقَالَ ‏ ‏عُمَرُ ‏ ‏لِمَنْ حَوْلَهُ مَا الرِّيحُ فَلَمْ يَرْجِعُوا إِلَيْهِ شَيْئًا فَبَلَغَنِي الَّذِي سَأَلَ عَنْهُ فَاسْتَحْثَثْتُ رَاحِلَتِي حَتَّى أَدْرَكْتُهُ فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ أُخْبِرْتُ أَنَّكَ سَأَلْتَ عَنْ الرِّيحِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الرِّيحُ مِنْ رَوْحِ اللَّهِ عَزَّ وَجَلَّ تَأْتِي بِالرَّحْمَةِ ‏ ‏وَتَأْتِي بِالْعَذَابِ فَلَا تَسُبُّوهَا وَسَلُوا اللَّهَ مِنْ خَيْرِهَا وَعُوذُوا بِهِ مِنْ شَرِّهَا ‏","","",""],[10297,10297,"","","‏ ‏حَدَّثَنَا ‏ ‏سَكَنُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[10298,10298,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[10299,10299,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏قَبِيصَةُ بْنُ ذُؤَيْبٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏نَهَى أَنْ يُجْمَعَ بَيْنَ الْمَرْأَةِ وَعَمَّتِهَا وَبَيْنَ الْمَرْأَةِ وَخَالَتِهَا ‏","","",""],[10300,10300,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَوَضَّأَ ‏ ‏فَلْيَسْتَنْثِرْ ‏ ‏وَمَنْ ‏ ‏اسْتَنْجَى ‏ ‏فَلْيُوتِرْ ‏","","",""],[10301,10301,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَعُدِّلَتْ الصُّفُوفُ قِيَامًا فَخَرَجَ إِلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا قَامَ فِي مُصَلَّاهُ ذَكَرَ أَنَّهُ جُنُبٌ فَقَالَ لَنَا مَكَانَكُمْ ثُمَّ رَجَعَ فَاغْتَسَلَ ثُمَّ خَرَجَ إِلَيْنَا وَرَأْسُهُ يَقْطُرُ فَكَبَّرَ فَصَلَّيْنَا مَعَهُ ‏","","",""],[10302,10302,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قُلْتَ لِصَاحِبِكَ وَالْإِمَامُ يَخْطُبُ يَوْمَ الْجُمُعَةِ أَنْصِتْ فَقَدْ ‏ ‏لَغَوْتَ ‏","","",""],[10303,10303,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ أَوْلَادِ الْمُشْرِكِينَ فَقَالَ ‏ ‏اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ ‏","","",""],[10304,10304,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏النَّاسُ أَكْثَرَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَلَقِيتُ رَجُلًا فَقُلْتُ بِأَيِّ سُورَةٍ قَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَارِحَةَ فِي الْعَتَمَةِ فَقَالَ لَا أَدْرِي فَقُلْتُ أَلَمْ تَشْهَدْهَا قَالَ بَلَى قُلْتُ وَلَكِنِّي أَدْرِي قَرَأَ سُورَةَ كَذَا وَكَذَا ‏","","",""],[10305,10305,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا طَلَعَتْ الشَّمْسُ وَلَا غَرَبَتْ عَلَى يَوْمٍ خَيْرٍ مِنْ يَوْمِ الْجُمُعَةِ هَدَانَا اللَّهُ لَهُ وَأَضَلَّ النَّاسَ عَنْهُ فَالنَّاسُ لَنَا فِيهِ تَبَعٌ هُوَ لَنَا ‏ ‏وَلِلْيَهُودِ ‏ ‏يَوْمُ السَّبْتِ ‏ ‏وَلِلنَّصَارَى ‏ ‏يَوْمُ الْأَحَدِ إِنَّ فِيهِ لَسَاعَةً لَا يُوَافِقُهَا مُؤْمِنٌ ‏ ‏يُصَلِّي يَسْأَلُ اللَّهَ عَزَّ وَجَلَّ شَيْئًا إِلَّا أَعْطَاهُ ‏","","",""],[10306,10306,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سِمْعَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَظْهَرَ الْفِتَنُ وَيَكْثُرَ الْكَذِبُ وَيَتَقَارَبَ الْأَسْوَاقُ وَيَتَقَارَبَ الزَّمَانُ وَيَكْثُرَ ‏ ‏الْهَرْجُ ‏ ‏قِيلَ وَمَا ‏ ‏الْهَرْجُ ‏ ‏قَالَ الْقَتْلُ ‏","","",""],[10307,10307,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏قَامَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏بَنِي كَعْبِ بْنِ لُؤَيٍّ ‏ ‏يَا ‏ ‏بَنِي هَاشِمٍ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ يَا ‏ ‏بَنِي عَبْدِ مَنَافٍ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ يَا ‏ ‏فَاطِمَةُ بِنْتَ مُحَمَّدٍ ‏ ‏أَنْقِذِي نَفْسَكِ مِنْ النَّارِ فَإِنِّي لَا أَمْلِكُ لَكُمْ مِنْ اللَّهِ شَيْئًا غَيْرَ أَنَّ لَكُمْ رَحِمًا ‏ ‏سَأَبُلُّهَا ‏ ‏بِبَلَالِهَا ‏","","",""],[10308,10308,"","","‏ ‏حَدَّثَنَا ‏ ‏مَحْبُوبُ بْنُ الْحَسَنِ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[10309,10309,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ يَعْنِي الطَّيَالِسِيَّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ الْخَزَّازُ ‏ ‏عَنْ ‏ ‏سَيَّارٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏عَائِشَةَ ‏ ‏فَدَخَلَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَقَالَتْ أَنْتَ الَّذِي تُحَدِّثُ ‏ ‏أَنَّ امْرَأَةً عُذِّبَتْ فِي هِرَّةٍ لَهَا رَبَطَتْهَا فَلَمْ تُطْعِمْهَا وَلَمْ تَسْقِهَا ‏ ‏فَقَالَ سَمِعْتُهُ مِنْهُ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏كَذَا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏فَقَالَتْ هَلْ تَدْرِي مَا كَانَتْ الْمَرْأَةُ إِنَّ الْمَرْأَةَ مَعَ مَا فَعَلَتْ كَانَتْ كَافِرَةً وَإِنَّ الْمُؤْمِنَ أَكْرَمُ عَلَى اللَّهِ عَزَّ وَجَلَّ مِنْ أَنْ يُعَذِّبَهُ فِي هِرَّةٍ فَإِذَا حَدَّثْتَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَانْظُرْ كَيْفَ تُحَدِّثُ ‏","","",""],[10310,10310,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏سَمِعَ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[10311,10311,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا شَرِبَ الْخَمْرَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاجْلِدُوهُ فَقَالَ فِي الرَّابِعَةِ فَاقْتُلُوهُ ‏","","",""],[10312,10312,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏شُتَيْرِ بْنِ نَهَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَدْخُلُ فُقَرَاءُ أُمَّتِي الْجَنَّةَ قَبْلَ أَغْنِيَائِهِمْ بِنِصْفِ يَوْمٍ قَالَ وَتَلَا ‏ { ‏وَإِنَّ يَوْمًا عِنْدَ رَبِّكَ كَأَلْفِ سَنَةٍ مِمَّا تَعُدُّونَ ‏}","","",""],[10313,10313,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَهَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يَرْفَعُهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا بَاتَتْ الْمَرْأَةُ هَاجِرَةً لِفِرَاشِ زَوْجِهَا لَعَنَتْهَا الْمَلَائِكَةُ حَتَّى تُصْبِحَ أَوْ حَتَّى تَرْجِعَ ‏","","",""],[10314,10314,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏الْمُثَنَّى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَاتَلَ أَحَدُكُمْ فَلْيَتَّقِ الْوَجْهَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ خَلَقَ ‏ ‏آدَمَ ‏ ‏عَلَى صُورَتِهِ ‏","","",""],[10315,10315,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي زِيَادٍ الطَّحَّانِ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ ‏ ‏يُنَجِّيهِ عَمَلُهُ قَالُوا وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ مِنْهُ بِرَحْمَةٍ ‏","","",""],[10316,10316,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ وَهُوَ أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ يَعْنِي الْقَطَّانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي لَيْلَةِ الْقَدْرِ إِنَّهَا لَيْلَةُ سَابِعَةٍ أَوْ تَاسِعَةٍ وَعِشْرِينَ إِنَّ الْمَلَائِكَةَ تِلْكَ اللَّيْلَةَ فِي الْأَرْضِ أَكْثَرُ مِنْ عَدَدِ الْحَصَى ‏","","",""],[10317,10317,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ ‏ ‏وَأَبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنَى ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنْ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَغَارُ وَإِنَّ الْمُؤْمِنَ يَغَارُ وَغَيْرَةُ اللَّهِ أَنْ يَأْتِيَ الْمُؤْمِنُ مَا حَرَّمَ عَلَيْهِ ‏","","",""],[10318,10318,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَابِسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏كُمَيْلَ بْنَ زِيَادٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَلَا أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ قُلْتُ بَلَى قَالَ ‏ ‏لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ‏ ‏قَالَ أَحْسِبُهُ قَالَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ أَسْلَمَ عَبْدِي وَاسْتَسْلَمَ ‏","","",""],[10319,10319,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ شَرِيكٍ ‏ ‏أَنَّ ‏ ‏الضَّحَّاكُ بْنُ قَيْسٍ ‏ ‏أَرْسَلَ مَعَهُ إِلَى ‏ ‏مَرْوَانَ ‏ ‏بِكِسْوَةٍ فَقَالَ ‏ ‏مَرْوَانُ ‏ ‏انْظُرُوا مَنْ تَرَوْنَ بِالْبَابِ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَأَذِنَ لَهُ فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَدِّثْنَا بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏سَمِعْتُهُ يَقُولُ ‏ ‏لَيَتَمَنَّيَنَّ أَقْوَامٌ وُلُّوا هَذَا الْأَمْرَ أَنَّهُمْ خَرُّوا مِنْ ‏ ‏الثُّرَيَّا ‏ ‏وَأَنَّهُمْ لَمْ يَلُوا شَيْئًا ‏","","",""],[10320,10320,"","","‏ ‏قَالَ ‏ ‏زِدْنَا يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَجْرِي هَلَاكُ هَذِهِ الْأُمَّةِ عَلَى يَدَيْ ‏ ‏أُغَيْلِمَةٍ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏","","",""],[10321,10321,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَلْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ مَيْمُونٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَرَّهُ أَنْ يَجِدَ طَعْمَ الْإِيمَانِ فَلْيُحِبَّ الْعَبْدَ لَا يُحِبُّهُ إِلَّا لِلَّهِ عَزَّ وَجَلَّ ‏","","",""],[10322,10322,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا يَدْعُو هَكَذَا بِأُصْبُعَيْهِ يُشِيرُ فَقَالَ أَحِّدْ أَحِّدْ ‏","","",""],[10323,10323,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مَجْرُوحٍ يُجْرَحُ فِي سَبِيلِ اللَّهِ وَاللَّهُ أَعْلَمُ بِمَنْ يُجْرَحُ فِي سَبِيلِهِ إِلَّا جَاءَ يَوْمَ الْقِيَامَةِ وَالْجُرْحُ كَهَيْئَتِهِ يَوْمَ جُرِحَ اللَّوْنُ لَوْنُ دَمٍ وَالرِّيحُ رِيحُ مِسْكٍ ‏","","",""],[10324,10324,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْحَيَّاتِ مَا سَالَمْنَاهُنَّ مُنْذُ حَارَبْنَاهُنَّ فَمَنْ تَرَكَ شَيْئًا خِيفَتَهُنَّ فَلَيْسَ مِنَّا ‏","","",""],[10325,10325,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏قَالَ ‏ ‏ابْنُ عَجْلَانَ ‏ ‏أَخْبَرَنَا عَنِ ‏ ‏الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ الْجَمْعِ تَفْضُلُ ذَاتَ ‏ ‏الْفَذِّ ‏ ‏خَمْسًا وَعِشْرِينَ دَرَجَةً ‏","","",""],[10326,10326,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَشُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَعَدَ بَيْنَ ‏ ‏شُعَبِهَا ‏ ‏الْأَرْبَعِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏ثُمَّ جَهَدَهَا ‏ ‏وَقَالَ ‏ ‏هِشَامٌ ‏ ‏ثُمَّ ‏ ‏اجْتَهَدَ ‏ ‏فَقَدْ وَجَبَ الْغُسْلُ ‏","","",""],[10327,10327,"","","‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ حَرْبٍ أَبُو صَالِحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَالِكَ بْنَ أَنَسٍ ‏ ‏وَذَكَرَ ‏ ‏سُفْيَانَ الثَّوْرِيَّ ‏ ‏فَقَالَ ‏ ‏أَمَا إِنَّهُ قَدْ فَارَقَنِي عَلَى أَنَّهُ لَا يَشْرَبُ ‏ ‏النَّبِيذَ ‏","","",""],[10328,10328,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ بْنَ سَعْدٍ ‏ ‏يَقُولُ ‏ ‏أَشْهَدُ عَلَى ‏ ‏سُفْيَانَ ‏ ‏أَنِّي سَأَلْتُهُ ‏ ‏أَوْ سُئِلَ ‏ ‏عَنْ النَّبِيذِ فَقَالَ ‏ ‏كُلْ تَمْرًا وَاشْرَبْ مَاءً يَصِيرُ فِي بَطْنِكَ ‏ ‏نَبِيذًا ‏","","",""],[10329,10329,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏يَعْنِي ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَلَسَ بَيْنَ ‏ ‏شُعَبِهَا ‏ ‏الْأَرْبَعِ ثُمَّ ‏ ‏اجْتَهَدَ ‏ ‏فَقَدْ وَجَبَ الْغُسْلُ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏ثُمَّ ‏ ‏جَهَدَهَا ‏","","",""],[10330,10330,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فِي ثَوْبٍ وَاحِدٍ فَلْيُخَالِفْ بَيْنَ طَرَفَيْهِ عَلَى ‏ ‏عَاتِقِهِ ‏","","",""],[10331,10331,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَثَّ عَلَيْهِ فَقَالَ رَجُلٌ عِنْدِي كَذَا وَكَذَا قَالَ فَمَا بَقِيَ فِي الْمَجْلِسِ رَجُلٌ إِلَّا قَدْ تَصَدَّقَ بِمَا قَلَّ أَوْ كَثُرَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَنَّ خَيْرًا ‏ ‏فَاسْتُنَّ ‏ ‏بِهِ كَانَ لَهُ أَجْرُهُ كَامِلًا وَمِنْ أُجُورِ مَنْ ‏ ‏اسْتَنَّ ‏ ‏بِهِ لَا يَنْقُصُ مِنْ أُجُورِهِمْ شَيْئًا وَمَنْ ‏ ‏اسْتَنَّ ‏ ‏شَرًّا ‏ ‏فَاسْتُنَّ ‏ ‏بِهِ فَعَلَيْهِ ‏ ‏وِزْرُهُ ‏ ‏كَامِلًا وَمِنْ ‏ ‏أَوْزَارِ ‏ ‏الَّذِي ‏ ‏اسْتَنَّ ‏ ‏بِهِ لَا يَنْقُصُ مِنْ ‏ ‏أَوْزَارِهِمْ ‏ ‏شَيْئًا ‏","","",""],[10332,10332,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعَتَيْنِ اللَّمْسِ ‏ ‏وَالنِّبَاذِ ‏","","",""],[10333,10333,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى مِنْ الصُّبْحِ رَكْعَةً ثُمَّ طَلَعَتْ الشَّمْسُ فَلْيُصَلِّ إِلَيْهَا أُخْرَى ‏","","",""],[10334,10334,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُذْكَرُ عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَجُلًا رَأَى كَلْبًا يَأْكُلُ ‏ ‏الثَّرَى ‏ ‏مِنْ الْعَطَشِ ‏ ‏فَأَخَذَ الرَّجُلُ ‏ ‏خُفَّهُ ‏ ‏فَجَعَلَ يَغْرِفُ لَهُ بِهِ الْمَاءَ حَتَّى ‏ ‏أَرْوَاهُ ‏ ‏فَشَكَرَ اللَّهُ عَزَّ وَجَلَّ لَهُ فَأَدْخَلَهُ الْجَنَّةَ ‏","","",""],[10335,10335,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَرَّ رَجُلٌ بِغُصْنِ شَوْكٍ فَنَحَّاهُ عَنْ الطَّرِيقِ فَشَكَرَ اللَّهُ لَهُ فَأَدْخَلَهُ الْجَنَّةَ ‏","","",""],[10336,10336,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَأَبُو عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فِي الرَّكْعَةِ الْآخِرَةِ مِنْ الْعِشَاءِ الْآخِرَةِ ‏ ‏قَنَتَ ‏ ‏وَقَالَ اللَّهُمَّ أَنْجِ ‏ ‏الْوَلِيدَ بْنَ الْوَلِيدِ ‏ ‏اللَّهُمَّ أَنْجِ ‏ ‏سَلَمَةَ بْنَ هِشَامٍ ‏ ‏اللَّهُمَّ أَنْجِ ‏ ‏عَيَّاشَ بْنَ أَبِي رَبِيعَةَ ‏ ‏اللَّهُمَّ أَنْجِ الْمُسْتَضْعَفِينَ مِنْ الْمُؤْمِنِينَ اللَّهُمَّ اشْدُدْ ‏ ‏وَطْأَتَكَ ‏ ‏عَلَى ‏ ‏مُضَرَ ‏ ‏اللَّهُمَّ اجْعَلْهَا ‏ ‏سِنِينَ ‏ ‏كَسِنِينَ ‏ ‏يُوسُفَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَالَ ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏كَسِنِي ‏ ‏يُوسُفَ ‏ ‏وَقَالَ فِيهَا كُلِّهَا نَجِّ نَجِّ ‏ ‏وَقَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏كُلِّهَا اللَّهُمَّ أَنْجِ أَنْجِ ‏","","",""],[10337,10337,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَأَبُو عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تَقَدَّمُوا ‏ ‏رَمَضَانَ بِيَوْمٍ وَلَا بِيَوْمَيْنِ إِلَّا أَنْ يَكُونَ رَجُلٌ كَانَ يَصُومُ صَوْمًا فَلْيَصُمْهُ ‏","","",""],[10338,10338,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَأَبُو عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ إِذَا بَقِيَ ثُلُثُ اللَّيْلِ ‏ ‏يَنْزِلُ اللَّهُ عَزَّ وَجَلَّ إِلَى سَمَاءِ الدُّنْيَا فَيَقُولُ مَنْ ذَا الَّذِي يَدْعُونِي أَسْتَجِبْ لَهُ مَنْ ذَا الَّذِي يَسْتَغْفِرُنِي أَغْفِرْ لَهُ مَنْ ذَا الَّذِي يَسْتَرْزِقُنِي أَرْزُقْهُ مَنْ ذَا الَّذِي يَسْتَكْشِفُ الضُّرَّ أَكْشِفْهُ حَتَّى ‏ ‏يَنْفَجِرَ ‏ ‏الصُّبْحُ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏","","",""],[10339,10339,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَأَبُو عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ الْإِيمَانِ عِنْدَ اللَّهِ عَزَّ وَجَلَّ إِيمَانٌ لَا شَكَّ فِيهِ وَغَزْوَةٌ لَيْسَ فِيهَا ‏ ‏غُلُولٌ ‏ ‏وَحَجَّةٌ مَبْرُورَةٌ ‏","","",""],[10340,10340,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏قَالَ ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏أَبِي مُزَاحِمٍ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَبِعَ جِنَازَةً وَصَلَّى عَلَيْهَا فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏وَمَنْ انْتَظَرَ حَتَّى يَقْضِيَ قَضَاءَهَا فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ وَمَا ‏ ‏الْقِيرَاطَانِ ‏ ‏قَالَ أَحَدُهُمَا مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[10341,10341,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏يَعْنِي ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ أَبِي عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَفَعَهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَيْلٌ لِلْوُزَرَاءِ ‏ ‏لَيَتَمَنَّى أَقْوَامٌ يَوْمَ الْقِيَامَةِ أَنَّ ‏ ‏ذَوَائِبَهُمْ ‏ ‏كَانَتْ مُعَلَّقَةً ‏ ‏بِالثُّرَيَّا ‏ ‏يَتَذَبْذَبُونَ بَيْنَ السَّمَاءِ وَالْأَرْضِ وَأَنَّهُمْ لَمْ يَلُوا عَمَلًا ‏","","",""],[10342,10342,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏قَالَ ‏ ‏بَلَغَنِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ يُعْطِي عَبْدَهُ الْمُؤْمِنَ بِالْحَسَنَةِ الْوَاحِدَةِ أَلْفَ أَلْفِ حَسَنَةٍ قَالَ فَقُضِيَ أَنِّي انْطَلَقْتُ حَاجًّا ‏ ‏أَوْ مُعْتَمِرًا ‏ ‏فَلَقِيتُهُ فَقُلْتُ بَلَغَنِي عَنْكَ حَدِيثٌ أَنَّكَ تَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ اللَّهَ عَزَّ وَجَلَّ يُعْطِي عَبْدَهُ الْمُؤْمِنَ الْحَسَنَةَ أَلْفَ أَلْفِ حَسَنَةٍ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏لَا بَلْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏يُعْطِيهِ أَلْفَيْ أَلْفِ حَسَنَةٍ ثُمَّ تَلَا ‏ { ‏يُضَاعِفْهَا وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا ‏} ‏فَقَالَ إِذَا قَالَ أَجْرًا عَظِيمًا فَمَنْ يَقْدُرُ قَدْرَهُ ‏","","",""],[10343,10343,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَتَرَ أَخَاهُ الْمُسْلِمَ سَتَرَ اللَّهُ عَلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[10344,10344,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْقَتِيلُ فِي سَبِيلِ اللَّهِ شَهِيدٌ ‏ ‏وَالْمَطْعُونُ ‏ ‏شَهِيدٌ ‏ ‏وَالْمَبْطُونُ ‏ ‏شَهِيدٌ وَمَنْ مَاتَ فِي سَبِيلِ اللَّهِ فَهُوَ شَهِيدٌ ‏","","",""],[10345,10345,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سُهَيْلٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ إِذَا أَصْبَحَ ‏ ‏اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا وَبِكَ ‏ ‏نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ الْمَصِيرُ ‏","","",""],[10346,10346,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏أَخْبَرَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَرْعَفَنَّ عَلَى مِنْبَرِي جَبَّارٌ مِنْ جَبَابِرَةِ ‏ ‏بَنِي أُمَيَّةَ ‏ ‏يَسِيلُ ‏ ‏رُعَافُهُ ‏ ‏قَالَ ‏ ‏فَحَدَّثَنِي ‏ ‏مَنْ ‏ ‏رَأَى ‏ ‏عَمْرَو بْنَ سَعِيدِ بْنِ الْعَاصِ ‏ ‏رَعَفَ ‏ ‏عَلَى مِنْبَرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى سَالَ ‏ ‏رُعَافُهُ ‏","","",""],[10347,10347,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عُبَيْدٍ الْهُنَائِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ شَقِيقٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ بَيْنَ ‏ ‏ضَجَنَانِ ‏ ‏وَعُسْفَانَ ‏ ‏فَقَالَ الْمُشْرِكُونَ إِنَّ لِهَؤُلَاءِ صَلَاةً هِيَ أَحَبُّ إِلَيْهِمْ مِنْ آبَائِهِمْ وَأَبْنَائِهِمْ وَهِيَ الْعَصْرُ فَأَجْمِعُوا أَمْرَكُمْ فَمِيلُوا عَلَيْهِمْ ‏ ‏مَيْلَةً ‏ ‏وَاحِدَةً وَإِنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُ أَنْ يَقْسِمَ أَصْحَابَهُ ‏ ‏شَطْرَيْنِ ‏ ‏فَيُصَلِّيَ بِبَعْضِهِمْ وَتَقُومَ الطَّائِفَةُ الْأُخْرَى وَرَاءَهُمْ وَلْيَأْخُذُوا حِذْرَهُمْ وَأَسْلِحَتَهُمْ ثُمَّ تَأْتِي الْأُخْرَى فَيُصَلُّونَ مَعَهُ وَيَأْخُذُ هَؤُلَاءِ حِذْرَهُمْ وَأَسْلِحَتَهُمْ لِتَكُونَ لَهُمْ رَكْعَةً رَكْعَةٌ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكْعَتَانِ ‏","","",""],[10348,10348,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ حَسَّانَ يَعْنِي الْعَنْبَرِيَّ ‏ ‏عَنِ ‏ ‏الْقَلُوصِ ‏ ‏أَنَّ ‏ ‏شِهَابَ بْنَ مُدْلِجٍ ‏ ‏نَزَلَ ‏ ‏الْبَادِيَةَ ‏ ‏فَسَابَّ ابْنُهُ رَجُلًا فَقَالَ يَا ابْنَ الَّذِي تَعَرَّبَ بِهَذِهِ الْهِجْرَةِ فَأَتَى ‏ ‏شِهَابٌ ‏ ‏الْمَدِينَةَ ‏ ‏فَلَقِيَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَسَمِعَهُ يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ النَّاسِ رَجُلَانِ رَجُلٌ غَزَا فِي سَبِيلِ اللَّهِ حَتَّى يَهْبِطَ مَوْضِعًا يَسُوءُ الْعَدُوَّ وَرَجُلٌ بِنَاحِيَةِ ‏ ‏الْبَادِيَةِ ‏ ‏يُقِيمُ الصَّلَوَاتِ الْخَمْسَ وَيُؤَدِّي حَقَّ مَالِهِ وَيَعْبُدُ رَبَّهُ حَتَّى يَأْتِيَهُ الْيَقِينُ ‏ ‏فَجَثَا ‏ ‏عَلَى رُكْبَتَيْهِ قَالَ أَنْتَ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ لَهُ قَالَ نَعَمْ فَأَتَى بَادِيَتَهُ فَأَقَامَ بِهَا ‏","","",""],[10349,10349,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزِّرَاعِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ أَنَا ‏ ‏وَعَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏وَسَمُرَةُ بْنُ جُنْدُبٍ ‏ ‏فَأَتَيْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا لَنَا انْطَلِقُوا إِلَى مَسْجِدِ التَّقْوَى فَانْطَلَقْنَا نَحْوَهُ فَاسْتَقْبَلْنَاهُ يَدَاهُ عَلَى كَاهِلِ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏فَثُرْنَا فِي وَجْهِهِ فَقَالَ ‏ ‏مَنْ هَؤُلَاءِ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏وَأَبُو هُرَيْرَةَ ‏ ‏وَسَمُرَةُ ‏","","",""],[10350,10350,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَعَذَابِ النَّارِ وَفِتْنَةِ الْمَحْيَا وَالْمَمَاتِ وَفِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏قَالَ ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏وَشَرِّ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏","","",""],[10351,10351,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا نُودِيَ لِلصَّلَاةِ ‏ ‏أَدْبَرَ ‏ ‏الشَّيْطَانُ وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ الْأَذَانَ فَإِذَا قُضِيَ الْأَذَانُ أَقْبَلَ فَإِذَا ‏ ‏ثُوِّبَ ‏ ‏بِهَا ‏ ‏أَدْبَرَ ‏ ‏فَإِذَا ‏ ‏قُضِيَ ‏ ‏التَّثْوِيبُ ‏ ‏أَقْبَلَ ‏ ‏يَخْطِرُ ‏ ‏بَيْنَ الْمَرْءِ وَقَلْبِهِ ‏ ‏أَوْ قَالَ نَفْسِهِ ‏ ‏يَقُولُ اذْكُرْ كَذَا اذْكُرْ كَذَا لِمَا لَمْ يَكُنْ يَذْكُرُ حَتَّى يَظَلَّ الرَّجُلُ لَا يَدْرِي كَمْ صَلَّى فَإِذَا لَمْ يَدْرِ أَحَدُكُمْ صَلَّى ثَلَاثًا أَوْ أَرْبَعًا فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ ‏","","",""],[10352,10352,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ نَافِعٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏ضَرَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلَ الْبَخِيلِ وَالْمُتَصَدِّقِ كَمَثَلِ رَجُلَيْنِ عَلَيْهِمَا ‏ ‏جُبَّتَانِ ‏ ‏مِنْ حَدِيدٍ قَدْ ‏ ‏اضْطُرَّتْ ‏ ‏أَيْدِيهِمَا إِلَى ثَدْيَيْهِمَا وَتَرَاقِيهِمَا فَجَعَلَ الْمُتَصَدِّقُ كُلَّمَا تَصَدَّقَ ‏ ‏بِصَدَقَةٍ ‏ ‏انْبَسَطَتْ عَنْهُ حَتَّى ‏ ‏تَغْشَى ‏ ‏أَنَامِلَهُ ‏ ‏وَتَعْفُوَ ‏ ‏أَثَرَهُ ‏ ‏وَجَعَلَ الْبَخِيلُ كُلَّمَا هَمَّ ‏ ‏بِصَدَقَةٍ ‏ ‏قَلَصَتْ ‏ ‏كُلُّ حَلْقَةٍ وَأَخَذَتْ بِمَكَانِهَا قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ فَأَنَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ بِإِصْبَعَيْهِ فِي جُبَّتِهِ فَلَوْ رَأَيْتَهُ يُوَسِّعُهَا وَلَا تُوَسَّعُ ‏","","",""],[10353,10353,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثُ دَعَوَاتٍ مُسْتَجَابَاتٌ لَا شَكَّ فِيهِنَّ دَعْوَةُ الْمَظْلُومِ وَدَعْوَةُ الْمُسَافِرِ وَدَعْوَةُ الْوَالِدِ عَلَى وَلَدِهِ ‏","","",""],[10354,10354,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا ‏ ‏بِالْأَعْمَالِ فِتَنًا كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ مُؤْمِنًا ‏ ‏وَيُمْسِي كَافِرًا ‏ ‏وَيُمْسِي مُؤْمِنًا وَيُصْبِحُ كَافِرًا يَبِيعُ دِينَهُ ‏ ‏بِعَرَضٍ ‏ ‏مِنْ الدُّنْيَا قَلِيلٍ ‏","","",""],[10355,10355,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏الْمُغِيرَةُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ بَنِي ‏ ‏آدَمَ ‏ ‏يَطْعُنُ الشَّيْطَانُ بِإِصْبَعِهِ فِي جَنْبِهِ حِينَ يُولَدُ إِلَّا ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏ ‏ذَهَبَ يَطْعُنُ فَطَعَنَ فِي الْحِجَابِ ‏","","",""],[10356,10356,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏الْمُغِيرَةُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَمَنَّوْا لِقَاءَ الْعَدُوِّ فَإِذَا لَقِيتُمُوهُ فَاصْبِرُوا ‏","","",""],[10357,10357,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَسُرَيْجٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الْمُؤْمِنِ مَثَلُ ‏ ‏خَامَةِ ‏ ‏الزَّرْعِ مِنْ حَيْثُ انْتَهَى الرِّيحُ كَفَتْهَا فَإِذَا سَكَنَتْ اعْتَدَلَتْ وَكَذَلِكَ مَثَلُ الْمُؤْمِنِ ‏ ‏يَتَكَفَّأُ ‏ ‏بِالْبَلَاءِ وَمَثَلُ الْكَافِرِ مَثَلُ ‏ ‏الْأَرْزَةِ ‏ ‏صَمَّاءُ ‏ ‏مُعْتَدِلَةٌ يَقْصِمُهَا اللَّهُ إِذَا شَاءَ ‏","","",""],[10358,10358,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ أَبِي يَعْقُوبَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُقِيمُ الرَّجُلُ الرَّجُلَ مِنْ مَجْلِسِهِ ثُمَّ يَجْلِسُ فِيهِ وَلَكِنْ افْسَحُوا يَفْسَحْ اللَّهُ لَكُمْ ‏","","",""],[10359,10359,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏الْمُغِيرَةُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا الْإِمَامُ ‏ ‏جُنَّةٌ ‏ ‏يُقَاتَلُ مِنْ وَرَائِهِ ‏ ‏وَيُتَّقَى بِهِ فَإِنْ أَمَرَ بِتَقْوَى وَعَدَلَ فَإِنَّ لَهُ بِذَلِكَ أَجْرًا وَإِنْ أَمَرَ بِغَيْرِ ذَلِكَ فَإِنَّ عَلَيْهِ فِيهِ وِزْرًا ‏","","",""],[10360,10360,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ رَقِيَ إِلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَلَى ظَهْرِ الْمَسْجِدِ فَوَجَدَهُ يَتَوَضَّأُ فَرَفَعَ فِي عَضُدَيْهِ ثُمَّ أَقْبَلَ عَلَيَّ ‏ ‏فَقَالَ ‏ ‏إِنِّي ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أُمَّتِي يَوْمَ الْقِيَامَةِ هِيَ ‏ ‏الْغُرُّ ‏ ‏الْمُحَجَّلُونَ ‏ ‏مِنْ أَثَرِ الْوُضُوءِ مَنْ اسْتَطَاعَ أَنْ يُطِيلَ ‏ ‏غُرَّتَهُ ‏ ‏فَلْيَفْعَلْ ‏ ‏لَا أَدْرِي مِنْ قَوْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مِنْ قَوْلِ ‏ ‏أَبِي هُرَيْرَةَ ‏","","",""],[10361,10361,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ يَعْنِي ابْنَ مَعْمَرٍ وَهُوَ أَبُو طُوَالَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ النَّاسِ رَجُلٌ أَخَذَ بِعِنَانِ فَرَسِهِ فِي سَبِيلِ اللَّهِ أَلَا أُخْبِرُكُمْ بِخَيْرِ النَّاسِ مَنْزِلَةً بَعْدَهُ رَجُلٌ مُعْتَزِلٌ فِي غَنَمٍ أَوْ ‏ ‏غُنَيْمَةٍ ‏ ‏يُقِيمُ الصَّلَاةَ ‏ ‏وَيُؤْتِي الزَّكَاةَ وَيَعْبُدُ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئًا ‏","","",""],[10362,10362,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ يَعْنِي ابْنَ مَعْمَرٍ أَبُو طُوَالَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ ‏أَيْنَ الْمُتَحَابُّونَ بِجَلَالِي ‏ ‏الْيَوْمَ أُظِلُّهُمْ فِي ظِلِّي يَوْمَ لَا ظِلَّ إِلَّا ظِلِّي ‏","","",""],[10363,10363,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَدَعَنَّ رِجَالٌ فَخْرَهُمْ بِأَقْوَامٍ إِنَّمَا هُمْ فَحْمٌ مِنْ فَحْمِ جَهَنَّمَ أَوْ لَيَكُونُنَّ أَهْوَنَ عَلَى اللَّهِ مِنْ ‏ ‏الْجِعْلَانِ ‏ ‏الَّتِي تَدْفَعُ بِأَنْفِهَا النَّتِنَ وَقَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَذْهَبَ عَنْكُمْ عُبِّيَّةَ الْجَاهِلِيَّةِ وَفَخْرَهَا بِالْآبَاءِ مُؤْمِنٌ تَقِيٌّ وَفَاجِرٌ شَقِيٌّ النَّاسُ بَنُو ‏ ‏آدَمَ ‏ ‏وَآدَمُ ‏ ‏مِنْ تُرَابٍ ‏","","",""],[10364,10364,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ اللَّهُ تَعَالَى ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي بِي وَأَنَا مَعَهُ حَيْثُ يَذْكُرُنِي وَاللَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ مِنْ أَحَدِكُمْ يَجِدُ ضَالَّتَهُ بِالْفَلَاةِ وَمَنْ يَتَقَرَّبُ إِلَيَّ شِبْرًا تَقَرَّبْتُ إِلَيْهِ ذِرَاعًا وَمَنْ تَقَرَّبَ إِلَيَّ ذِرَاعًا تَقَرَّبْتُ إِلَيْهِ بَاعًا وَإِذَا أَقْبَلَ يَمْشِي أَقْبَلْتُ أُهَرْوِلُ ‏","","",""],[10365,10365,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ تَمِيمٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَظَلَّكُمْ شَهْرُكُمْ هَذَا بِمَحْلُوفِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مَرَّ بِالْمُسْلِمِينَ شَهْرٌ قَطُّ خَيْرٌ لَهُمْ مِنْهُ وَمَا مَرَّ بِالْمُنَافِقِينَ شَهْرٌ قَطُّ أَشَرُّ لَهُمْ مِنْهُ بِمَحْلُوفِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَيَكْتُبُ أَجْرَهُ وَنَوَافِلَهُ وَيَكْتُبُ إِصْرَهُ وَشَقَاءَهُ مِنْ قَبْلِ أَنْ يُدْخِلَهُ وَذَاكَ لِأَنَّ الْمُؤْمِنَ يُعِدُّ فِيهِ الْقُوَّةَ مِنْ النَّفَقَةِ لِلْعِبَادَةِ وَيُعِدُّ فِيهِ الْمُنَافِقُ ابْتِغَاءَ غَفَلَاتِ الْمُؤْمِنِينَ وَعَوْرَاتِهِمْ فَهُوَ غُنْمٌ لِلْمُؤْمِنِ يَغْتَنِمُهُ الْفَاجِرُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ وَهُوَ أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَظَلَّكُمْ شَهْرُكُمْ ‏ ‏فَذَكَرَهُ ‏","","",""],[10366,10366,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ ‏ ‏الصَّدَقَةِ ‏ ‏مَا كَانَ عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى وَابْدَأْ بِمَنْ تَعُولُ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏مَا مَنْ ‏ ‏تَعُولُ ‏ ‏قَالَ امْرَأَتُكَ تَقُولُ أَطْعِمْنِي ‏ ‏أَوْ أَنْفِقْ عَلَيَّ شَكَّ ‏ ‏أَبُو عَامِرٍ ‏ ‏أَوْ طَلِّقْنِي ‏ ‏وَخَادِمُكَ يَقُولُ أَطْعِمْنِي وَاسْتَعْمِلْنِي وَابْنَتُكَ تَقُولُ إِلَى مَنْ تَذَرُنِي ‏","","",""],[10367,10367,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذُبَابٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِشِعْبٍ فِيهِ ‏ ‏عُيَيْنَةُ مَاءٍ عَذْبٍ فَأَعْجَبَهُ طِيبُهُ فَقَالَ لَوْ أَقَمْتُ فِي هَذَا ‏ ‏الشِّعْبِ ‏ ‏فَاعْتَزَلْتُ النَّاسَ وَلَا أَفْعَلُ حَتَّى أَسْتَأْمِرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا تَفْعَلْ فَإِنَّ مَقَامَ أَحَدِكُمْ فِي سَبِيلِ اللَّهِ خَيْرٌ مِنْ صَلَاةِ سِتِّينَ عَامًا خَالِيًا أَلَا تُحِبُّونَ أَنْ يَغْفِرَ اللَّهُ لَكُمْ وَيُدْخِلَكُمْ الْجَنَّةَ اغْزُوا فِي سَبِيلِ اللَّهِ مَنْ قَاتَلَ فِي سَبِيلِ اللَّهِ ‏ ‏فُوَاقَ ‏ ‏نَاقَةٍ وَجَبَتْ لَهُ الْجَنَّةُ ‏","","",""],[10368,10368,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ ‏ ‏ذَكَرَ رَجُلَيْنِ ادَّعَيَا دَابَّةً وَلَمْ يَكُنْ لَهُمَا بَيِّنَةٌ ‏ ‏فَأَمَرَهُمَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يَسْتَهِمَا ‏ ‏عَلَى الْيَمِينِ ‏","","",""],[10369,10369,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَنْظَلَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُقْبَضُ ‏ ‏الْعِلْمُ وَتَظْهَرُ الْفِتَنُ وَيَكْثُرُ ‏ ‏الْهَرْجُ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ وَمَا ‏ ‏الْهَرْجُ ‏ ‏قَالَ بِيَدِهِ هَكَذَا ‏ ‏يَعْنِي الْقَتْلَ ‏","","",""],[10370,10370,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْكُمْ ‏ ‏يَعْنِي أَحَدٌ يُدْخِلُهُ عَمَلُهُ الْجَنَّةَ وَلَا ‏ ‏يُنَجِّيهِ مِنْ النَّارِ قَالُوا وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ مِنْهُ بِرَحْمَةٍ وَفَضْلٍ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏","","",""],[10371,10371,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ رَاشِدٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏طِيَرَةَ ‏ ‏وَخَيْرُهَا الْفَأْلُ قِيلَ وَمَا الْفَأْلُ قَالَ الْكَلِمَةُ الصَّالِحَةُ يَسْمَعُهَا أَحَدُكُمْ ‏","","",""],[10372,10372,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏يُونُسَ بْنَ يَزِيدَ الْأَيْلِيَّ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَجِدُونَ النَّاسَ مَعَادِنَ فَخِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا فَقِهُوا وَتَجِدُونَ مِنْ خَيْرِ النَّاسِ فِي هَذَا الْأَمْرِ أَكْرَهَهُمْ لَهُ قَبْلَ أَنْ يَدْخُلَ فِيهِ وَتَجِدُونَ مِنْ شَرِّ النَّاسِ ذَا الْوَجْهَيْنِ الَّذِي يَأْتِي هَؤُلَاءِ بِوَجْهٍ وَهَؤُلَاءِ بِوَجْهٍ ‏","","",""],[10373,10373,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏يُونُسَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَقَارَبُ الزَّمَانُ وَيَفِيضُ الْمَالُ وَتَظْهَرُ الْفِتَنُ وَيَكْثُرُ الْهَرْجُ قَالُوا وَمَا الْهَرْجُ يَا رَسُولَ اللَّهِ قَالَ الْقَتْلُ الْقَتْلُ ‏","","",""],[10374,10374,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَجَاوَزُوا فِي الصَّلَاةِ فَإِنَّ خَلْفَكُمْ الضَّعِيفَ وَالْكَبِيرَ وَذَا الْحَاجَةِ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ التَّيْمِيُّ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الِلَّهِ ‏ ‏بِمِثْلِ ذَلِكَ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ عَبْدِ اللَّهِ ‏ ‏مِثْلَ ذَلِكَ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[10375,10375,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا رَجُلٍ أَفْلَسَ فَوَجَدَ رَجُلٌ عِنْدَهُ مَالَهُ وَلَمْ يَكُنْ ‏ ‏اقْتَضَى ‏ ‏مِنْ مَالِهِ شَيْئًا فَهُوَ لَهُ ‏","","",""],[10376,10376,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ رُزَيْقٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏كُمَيْلِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نَخْلِ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَوْ يَا ‏ ‏أَبَا هِرٍّ ‏ ‏هَلَكَ الْمُكْثِرُونَ إِنَّ الْمُكْثِرِينَ الْأَقَلُّونَ يَوْمَ الْقِيَامَةِ إِلَّا مَنْ قَالَ بِالْمَالِ هَكَذَا وَهَكَذَا وَقَلِيلٌ مَا هُمْ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَلَا أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ وَلَا مَلْجَأَ مِنْ اللَّهِ إِلَّا إِلَيْهِ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏هَلْ تَدْرِي مَا حَقُّ اللَّهِ عَلَى الْعِبَادِ وَمَا حَقُّ الْعِبَادِ عَلَى اللَّهِ قَالَ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَإِنَّ حَقَّ اللَّهِ عَلَى الْعِبَادِ أَنْ يَعْبُدُوهُ وَلَا يُشْرِكُوا بِهِ شَيْئًا وَإِنَّ حَقَّ الْعِبَادِ عَلَى اللَّهِ أَنْ لَا يُعَذِّبَ مَنْ فَعَلَ ذَلِكَ مِنْهُمْ ‏","","",""],[10377,10377,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ نَبْهَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبِعْ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[10378,10378,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَإِذَا لَقِيتُمْ الْمُشْرِكِينَ فِي الطَّرِيقِ فَلَا تَبْدَءُوهُمْ بِالسَّلَامِ وَاضْطَرُّوهُمْ إِلَى أَضْيَقِهَا ‏","","",""],[10379,10379,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ أَبِي الشَّعْثَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَفْضُلُ الصَّلَاةُ فِي جَمَاعَةٍ عَلَى صَلَاةِ ‏ ‏الْفَذِّ ‏ ‏بِخَمْسٍ وَعِشْرِينَ صَلَاةً ‏","","",""],[10380,10380,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرُ بْنُ يَسَافٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَدْرٍ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَى صَلَاةِ رَجُلٍ لَا يُقِيمُ صُلْبَهُ بَيْنَ رُكُوعِهِ وَسُجُودِهِ ‏","","",""],[10381,10381,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ يَعْنِي ابْنَ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَيُبَيِّتُ الْقَوْمَ بِالنِّعْمَةِ ثُمَّ يُصْبِحُونَ وَأَكْثَرُهُمْ كَافِرُونَ يَقُولُونَ مُطِرْنَا بِنَجْمِ كَذَا وَكَذَا ‏ ‏قَالَ ‏ ‏فَحَدَّثْتُ ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏فَقَالَ ‏ ‏وَنَحْنُ قَدْ سَمِعْنَا ذَلِكَ مِنْ ‏ ‏أَبِي هُرَيْرَةَ ‏","","",""],[10382,10382,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏وَاقِدُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَاصِمٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ ابْنِ مَرْجَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا امْرِئٍ مُسْلِمٍ أَعْتَقَ امْرَأً مُسْلِمًا اسْتَنْقَذَهُ اللَّهُ مِنْ النَّارِ كُلَّ عُضْوٍ مِنْهُ عُضْوًا مِنْهُ ‏","","",""],[10383,10383,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْجِدَ لِصَلَاةِ الْعِشَاءِ الْآخِرَةِ فَإِذَا هُمْ ‏ ‏عِزُونَ ‏ ‏مُتَفَرِّقُونَ فَغَضِبَ غَضَبًا مَا رَأَيْتُهُ غَضِبَ غَضَبًا قَطُّ أَشَدَّ مِنْهُ ثُمَّ قَالَ لَوْ أَنَّ رَجُلًا نَادَى النَّاسَ إِلَى ‏ ‏عَرْقٍ ‏ ‏أَوْ مِرْمَاتَيْنِ لَأَتَوْهُ لِذَلِكَ وَهُمْ يَتَخَلَّفُونَ عَنْ الصَّلَاةِ ‏ ‏لَقَدْ هَمَمْتُ أَنْ آمُرَ رَجُلًا فَلْيُصَلِّ بِالنَّاسِ ثُمَّ ‏ ‏أَتْبَعَ ‏ ‏أَهْلَ هَذِهِ الدُّورِ الَّتِي يَتَخَلَّفُ أَهْلُهَا عَنْ هَذِهِ الصَّلَاةِ ‏ ‏فَأُضْرِمَهَا ‏ ‏عَلَيْهِمْ بِالنِّيرَانِ ‏","","",""],[10384,10384,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏قُطْبَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةُ ‏ ‏حَرَمٌ ‏ ‏فَمَنْ ‏ ‏أَحْدَثَ ‏ ‏فِيهَا ‏ ‏حَدَثًا ‏ ‏أَوْ ‏ ‏آوَى ‏ ‏مُحْدِثًا ‏ ‏فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏عَدْلًا ‏ ‏وَلَا ‏ ‏صَرْفًا ‏","","",""],[10385,10385,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏زِيَادٍ الْحَارِثِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ لَهُ رَجُلٌ أَنْتَ الَّذِي ‏ ‏تَنْهَى النَّاسَ عَنْ صَوْمِ يَوْمِ الْجُمُعَةِ قَالَ فَقَالَ هَا وَرَبِّ هَذِهِ ‏ ‏الْكَعْبَةِ ‏ ‏هَا وَرَبِّ هَذِهِ ‏ ‏الْكَعْبَةِ ‏ ‏ثَلَاثًا لَقَدْ سَمِعْتُ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَصُومُ أَحَدُكُمْ يَوْمَ الْجُمُعَةِ وَحْدَهُ إِلَّا فِي أَيَّامٍ مَعَهُ ‏","","",""],[10386,10386,"","","‏ ‏وَلَقَدْ ‏ ‏رَأَيْتُ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَعَلَيْهِ نَعْلَاهُ وَيَنْصَرِفُ وَهُمَا عَلَيْهِ ‏","","",""],[10387,10387,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْخَمْرُ مِنْ هَاتَيْنِ الشَّجَرَتَيْنِ النَّخْلَةِ وَالْعِنَبَةِ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَنْبِذُوا ‏ ‏التَّمْرَ وَالزَّبِيبَ جَمِيعًا وَلَا ‏ ‏تَنْبِذُوا ‏ ‏الْبُسْرَ ‏ ‏وَالتَّمْرَ جَمِيعًا ‏ ‏وَانْتَبِذُوا ‏ ‏كُلَّ وَاحِدَةٍ مِنْهُنَّ عَلَى حِدَةٍ ‏","","",""],[10388,10388,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏لَهِيعَةَ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏قَدْ سَمَّاهُ ‏ ‏حَدَّثَنِي ‏ ‏سَلَمَةُ بْنُ قَيْصَرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ يَوْمًا ابْتِغَاءَ وَجْهِ اللَّهِ تَعَالَى بَعَّدَهُ اللَّهُ عَزَّ وَجَلَّ مِنْ جَهَنَّمَ كَبُعْدِ غُرَابٍ طَارَ وَهُوَ فَرْخٌ حَتَّى مَاتَ هَرِمًا ‏","","",""],[10389,10389,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏أَبِي الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعٌ مِنْ أَمْرِ الْجَاهِلِيَّةِ لَنْ يَدَعَهُنَّ النَّاسُ ‏ ‏النِّيَاحَةُ ‏ ‏وَالطَّعْنُ ‏ ‏فِي الْأَنْسَابِ ‏ ‏وَالْأَنْوَاءُ ‏ ‏يَقُولُ الرَّجُلُ سُقِينَا ‏ ‏بِنَوْءِ ‏ ‏كَذَا وَكَذَا وَالْإِعْدَاءُ أُجْرِبَ بَعِيرٌ فَأَجْرَبَ مِائَةً فَمَنْ أَعْدَى الْأَوَّلَ ‏","","",""],[10390,10390,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِلَّهِ عَزَّ وَجَلَّ مِائَةَ رَحْمَةٍ فَجَعَلَ مِنْهَا رَحْمَةً فِي الدُّنْيَا تَتَرَاحَمُونَ بِهَا وَعِنْدَهُ تِسْعَةٌ وَتِسْعُونَ رَحْمَةً فَإِذَا كَانَ يَوْمُ الْقِيَامَةِ ضَمَّ هَذِهِ الرَّحْمَةَ إِلَى التِّسْعَةِ وَالتِّسْعِينَ رَحْمَةً ثُمَّ عَادَ بِهِنَّ عَلَى خَلْقِهِ ‏","","",""],[10391,10391,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَلْقَمَةُ بْنُ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏أَبِي الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْعُو ‏ ‏اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَإِسْرَافِي وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ ‏","","",""],[10392,10392,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَقِيلٍ زُهْرَةُ بْنُ مَعْبَدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏مَعْبَدِ بْنِ عَبْدِ اللَّهِ بْنِ هِشَامٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏أَوْصَانِي خَلِيلِي بِثَلَاثٍ لَا أَدَعُهُنَّ حَتَّى أَمُوتَ ‏ ‏أَوْصَانِي بِرَكْعَتَيْ الضُّحَى وَبِصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَأَنْ لَا أَنَامَ إِلَّا عَلَى وِتْرٍ ‏","","",""],[10393,10393,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ رَبِيعَةَ الْقُرَشِيُّ ‏ ‏أَنَّ ‏ ‏عِرَاكَ بْنَ مَالِكٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏تَرْغَبُوا ‏ ‏عَنْ آبَائِكُمْ فَمَنْ رَغِبَ عَنْ أَبِيهِ فَإِنَّهُ كُفْرٌ ‏","","",""],[10394,10394,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏أَنَّ ‏ ‏سَعْدَ بْنَ أَبِي سَعِيدٍ الْمَقْبُرِيَّ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ إِنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ دَخَلَ مَسْجِدَنَا هَذَا يَتَعَلَّمُ خَيْرًا أَوْ يُعَلِّمُهُ كَانَ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ وَمَنْ دَخَلَهُ لِغَيْرِ ذَلِكَ كَانَ كَالنَّاظِرِ إِلَى مَا لَيْسَ لَهُ ‏","","",""],[10395,10395,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو صَخْرٍ ‏ ‏أَنَّ ‏ ‏يَزِيدَ بْنَ عَبْدِ اللَّهِ بْنِ قُسَيْطٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ أَحَدٍ يُسَلِّمُ عَلَيَّ إِلَّا رَدَّ اللَّهُ عَزَّ وَجَلَّ عَلَيَّ رُوحِي حَتَّى أَرُدَّ عَلَيْهِ السَّلَامَ ‏","","",""],[10396,10396,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوْلَى بِالْمُؤْمِنِ مِنْ نَفْسِهِ مَنْ تَرَكَ دَيْنًا أَوْ ضَيَاعًا فَإِلَيَّ وَلَا ضَيَاعَ عَلَيْهِ فَلْيُدْعَ لَهُ وَأَنَا وَلِيُّهُ وَمَنْ تَرَكَ مَالًا ‏ ‏فَلِلْعَصَبَةِ ‏ ‏مَنْ كَانَ ‏","","",""],[10397,10397,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا ‏","","",""],[10398,10398,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ ‏ ‏الصَّدَقَةِ ‏ ‏مَا كَانَ مِنْهَا عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏ ‏فَقِيلَ مَنْ ‏ ‏أَعُولُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ امْرَأَتُكَ مِمَّنْ ‏ ‏تَعُولُ ‏ ‏تَقُولُ أَطْعِمْنِي وَإِلَّا فَارِقْنِي ‏ ‏وَجَارِيَتُكَ ‏ ‏تَقُولُ أَطْعِمْنِي وَاسْتَعْمِلْنِي وَوَلَدُكَ يَقُولُ إِلَى مَنْ تَتْرُكُنِي ‏","","",""],[10399,10399,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏وَأَبُو عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏وَمَنْ أَظْلَمُ مِمَّنْ خَلَقَ كَخَلْقِي فَلْيَخْلُقُوا بَعُوضَةً وَلْيَخْلُقُوا ذَرَّةً ‏ ‏قَالَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏يَخْلُقُ ‏","","",""],[10400,10400,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ ‏ ‏الْأَنْصَارَ ‏ ‏أَحَبَّهُ اللَّهُ وَمَنْ أَبْغَضَ ‏ ‏الْأَنْصَارَ ‏ ‏أَبْغَضَهُ اللَّهُ ‏","","",""]];
